// Drag-a-rectangle (marquee) selection for an asset grid/list. DOM-driven
// (getBoundingClientRect, scrolling, an overlay box) but store-agnostic: the host
// injects how to find selectable cards, read the current selection, and write the
// new one. This decouples the controller from any particular store shape or
// shadow-DOM layout — light-dam queries one shadow root by `[data-uuid]`;
// asset-picker pierces per-component roots and maps uuids back to full objects.
// See plan/12 D10.
import type { ReactiveController, ReactiveControllerHost } from 'lit';

export interface MarqueeRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** A selectable card the marquee can cover, located by the host's query strategy. */
export interface MarqueeCard {
  uuid: string;
  el: HTMLElement;
}

export interface MarqueeOptions {
  /** Find every selectable card under the scroll container (host owns shadow-piercing). */
  queryCards: (container: HTMLElement) => MarqueeCard[];
  /**
   * The base selection the marquee extends, decided from the mousedown event — this is where
   * the host owns the add-vs-replace policy. Return `[]` to start fresh (replace) or the current
   * selection to extend it. e.g. light-dam: current selection only when a modifier is held;
   * asset-picker: always the current selection (its marquee is always additive).
   */
  getSelection: (e: MouseEvent) => Iterable<string>;
  /** Push the marquee's covered set back to the host's store. */
  setSelection: (uuids: Set<string>) => void;
  /**
   * Whether a mousedown landed on something that should keep its own behaviour (a card, a
   * control) rather than starting a marquee. Defaults to: any `[data-uuid]` element, table
   * row/table, button/input/anchor. Override when cards use other markers.
   */
  isInteractiveTarget?: (e: MouseEvent) => boolean;
}

const DRAG_THRESHOLD = 5; // px of movement before a drag counts as a marquee
const SCROLL_EDGE_SIZE = 40; // distance from an edge that triggers auto-scroll
const SCROLL_SPEED = 15; // max auto-scroll px per frame

export class MarqueeController implements ReactiveController {
  isActive = false;
  rect: MarqueeRect = { x: 0, y: 0, width: 0, height: 0 };

  private container?: HTMLElement;
  private startX = 0;
  private startY = 0;
  private startClientX = 0;
  private startClientY = 0;
  private preMarquee = new Set<string>();
  private dragging = false;
  private scrollRAF: number | null = null;
  private lastMouseEvent: MouseEvent | null = null;
  // Card geometry snapshotted at drag-start in content-coordinate space (stable
  // across scroll), so each mousemove tests cached rects instead of reflowing.
  private cardRects: Array<{ uuid: string; x: number; y: number; w: number; h: number }> = [];
  // The selection last pushed — lets us skip redundant setSelection() calls (and
  // the re-render each triggers) while the covered set is unchanged.
  private appliedSelection: Set<string> | null = null;

  private readonly handleMouseDown = (e: MouseEvent) => this.onMouseDown(e);
  private readonly handleMouseMove = (e: MouseEvent) => this.onMouseMove(e);
  private readonly handleMouseUp = () => this.onMouseUp();
  private readonly preventSelect = (e: Event) => e.preventDefault();

  constructor(
    private readonly host: ReactiveControllerHost,
    private readonly options: MarqueeOptions,
  ) {
    host.addController(this);
  }

  hostConnected(): void {}
  hostDisconnected(): void {
    this.detach();
  }

  /** Bind to the scroll container. Idempotent — re-binds cleanly. */
  attach(container: HTMLElement): void {
    if (this.container === container) return;
    this.detach();
    this.container = container;
    container.addEventListener('mousedown', this.handleMouseDown);
  }

  detach(): void {
    this.container?.removeEventListener('mousedown', this.handleMouseDown);
    document.removeEventListener('mousemove', this.handleMouseMove);
    document.removeEventListener('mouseup', this.handleMouseUp);
    document.removeEventListener('selectstart', this.preventSelect);
    this.stopAutoScroll();
    this.container?.classList.remove('marqueeing');
    this.container = undefined;
    this.lastMouseEvent = null;
    this.cardRects = [];
    this.appliedSelection = null;
  }

  // Only start a marquee from empty space: clicks on a card/row/control keep
  // their own behaviour (open preview, toggle checkbox, run an action).
  private isInteractiveTarget(e: MouseEvent): boolean {
    if (this.options.isInteractiveTarget) return this.options.isInteractiveTarget(e);
    return e.composedPath().some((el) => {
      if (!(el instanceof HTMLElement)) return false;
      if (
        el instanceof HTMLButtonElement ||
        el instanceof HTMLInputElement ||
        el instanceof HTMLAnchorElement
      )
        return true;
      return el.hasAttribute('data-uuid') || el.tagName === 'TR' || el.tagName === 'TABLE';
    });
  }

  private onMouseDown(e: MouseEvent): void {
    if (e.button !== 0 || !this.container || this.isInteractiveTarget(e)) return;
    const rect = this.container.getBoundingClientRect();
    this.startX = e.clientX - rect.left + this.container.scrollLeft;
    this.startY = e.clientY - rect.top + this.container.scrollTop;
    this.startClientX = e.clientX;
    this.startClientY = e.clientY;
    // The host decides the base selection from the event (add vs replace).
    this.preMarquee = new Set(this.options.getSelection(e));
    this.dragging = false;
    this.isActive = false;
    document.addEventListener('mousemove', this.handleMouseMove);
    document.addEventListener('mouseup', this.handleMouseUp);
  }

  private onMouseMove(e: MouseEvent): void {
    if (!this.container) return;
    if (!this.dragging) {
      const dx = Math.abs(e.clientX - this.startClientX);
      const dy = Math.abs(e.clientY - this.startClientY);
      if (dx < DRAG_THRESHOLD && dy < DRAG_THRESHOLD) return;
      // Threshold passed — this is a marquee, not a click. Suppress text
      // selection for the duration of the drag and drop any range already made.
      this.dragging = true;
      this.isActive = true;
      this.container.classList.add('marqueeing');
      document.addEventListener('selectstart', this.preventSelect);
      window.getSelection()?.removeAllRanges();
      this.cacheCards();
    }
    this.lastMouseEvent = e;
    this.updateRect(e);
    this.maybeAutoScroll(e);
  }

  private updateRect(e: MouseEvent): void {
    if (!this.container) return;
    const cr = this.container.getBoundingClientRect();
    const curX = e.clientX - cr.left + this.container.scrollLeft;
    const curY = e.clientY - cr.top + this.container.scrollTop;

    let x = Math.min(this.startX, curX);
    let y = Math.min(this.startY, curY);
    let width = Math.abs(curX - this.startX);
    let height = Math.abs(curY - this.startY);

    // Clamp into the content box so the box can't draw past the scroll area.
    if (x < 0) {
      width += x;
      x = 0;
    }
    if (y < 0) {
      height += y;
      y = 0;
    }
    if (x + width > this.container.scrollWidth) width = this.container.scrollWidth - x;
    if (y + height > this.container.scrollHeight) height = this.container.scrollHeight - y;

    this.rect = { x, y, width, height };
    this.applyBoxStyle();
    this.selectIntersecting();
  }

  private maybeAutoScroll(e: MouseEvent): void {
    if (!this.container || this.container.scrollHeight <= this.container.clientHeight) {
      this.stopAutoScroll();
      return;
    }
    const cr = this.container.getBoundingClientRect();
    const needs = e.clientY - cr.top < SCROLL_EDGE_SIZE || cr.bottom - e.clientY < SCROLL_EDGE_SIZE;
    if (needs && this.scrollRAF == null) {
      this.scrollRAF = requestAnimationFrame(() => this.autoScrollTick());
    } else if (!needs) {
      this.stopAutoScroll();
    }
  }

  private autoScrollTick(): void {
    this.scrollRAF = null;
    if (!this.container || !this.dragging || !this.lastMouseEvent) return;
    if (this.container.scrollHeight <= this.container.clientHeight) return;
    const cr = this.container.getBoundingClientRect();
    const e = this.lastMouseEvent;
    const distTop = e.clientY - cr.top;
    const distBottom = cr.bottom - e.clientY;
    let delta = 0;
    if (distTop < SCROLL_EDGE_SIZE) delta = -SCROLL_SPEED * (1 - distTop / SCROLL_EDGE_SIZE);
    else if (distBottom < SCROLL_EDGE_SIZE)
      delta = SCROLL_SPEED * (1 - distBottom / SCROLL_EDGE_SIZE);
    if (delta !== 0) {
      this.container.scrollTop += delta;
      this.updateRect(e);
      this.scrollRAF = requestAnimationFrame(() => this.autoScrollTick());
    }
  }

  private stopAutoScroll(): void {
    if (this.scrollRAF != null) {
      cancelAnimationFrame(this.scrollRAF);
      this.scrollRAF = null;
    }
  }

  private onMouseUp(): void {
    document.removeEventListener('mousemove', this.handleMouseMove);
    document.removeEventListener('mouseup', this.handleMouseUp);
    document.removeEventListener('selectstart', this.preventSelect);
    this.stopAutoScroll();
    this.lastMouseEvent = null;
    if (this.dragging) {
      this.dragging = false;
      this.isActive = false;
      this.rect = { x: 0, y: 0, width: 0, height: 0 };
      this.cardRects = [];
      this.appliedSelection = null;
      this.container?.classList.remove('marqueeing');
      this.host.requestUpdate();
    }
  }

  /** Snapshot every selectable card's rect once, in content-coordinate space. */
  private cacheCards(): void {
    if (!this.container) return;
    const cr = this.container.getBoundingClientRect();
    const sl = this.container.scrollLeft;
    const st = this.container.scrollTop;
    this.cardRects = [];
    for (const { uuid, el } of this.options.queryCards(this.container)) {
      if (!uuid) continue;
      const r = el.getBoundingClientRect();
      this.cardRects.push({
        uuid,
        x: r.left - cr.left + sl,
        y: r.top - cr.top + st,
        w: r.width,
        h: r.height,
      });
    }
  }

  /**
   * Position the overlay box imperatively so a drag doesn't re-render the grid on
   * every mousemove (only selection changes do). Falls back to one render when the
   * box isn't in the DOM yet (first frame after the drag threshold is crossed).
   */
  private applyBoxStyle(): void {
    const box = this.container?.querySelector<HTMLElement>('.marquee-box');
    if (!box) {
      this.host.requestUpdate();
      return;
    }
    box.style.left = `${this.rect.x}px`;
    box.style.top = `${this.rect.y}px`;
    box.style.width = `${this.rect.width}px`;
    box.style.height = `${this.rect.height}px`;
  }

  private static sameSet(a: Set<string>, b: Set<string> | null): boolean {
    if (!b || a.size !== b.size) return false;
    for (const v of a) if (!b.has(v)) return false;
    return true;
  }

  private selectIntersecting(): void {
    const next = new Set(this.preMarquee);
    const { x, y, width, height } = this.rect;
    for (const c of this.cardRects) {
      if (x < c.x + c.w && x + width > c.x && y < c.y + c.h && y + height > c.y) {
        next.add(c.uuid);
      }
    }
    // Skip the store update (and re-render) when the covered set is unchanged.
    if (MarqueeController.sameSet(next, this.appliedSelection)) return;
    this.appliedSelection = next;
    this.options.setSelection(next);
  }
}
