// FUTURE @scaleflex/dam-core — files service. See ../README.md.
//
// getFiles mirrors @scaleflex/asset-picker. rename/delete/move are light-dam's
// management layer, verified against js-admin-react-filerobot-v5.
import type { DamClient } from './dam-client';
import type { Asset, AssetType } from '../types/asset.types';
import type { GetFilesResponse, RawFile, ApiStatusResponse } from '../types/api.types';
import { ASSET_SORT_FIELDS, compareAssetsBySort } from '../folders/multi-folder-feed';
import { isVisibilityPublic } from '../helpers/display-url';

/** File-type categories the backend can filter on (`type:"image"` …). */
export type FileTypeFilter = 'image' | 'video' | 'audio' | 'document' | 'other';

/** Coarse file-size buckets (in bytes), mapped to a `size:"min..max"` clause. */
export type SizeBucket = 'small' | 'medium' | 'large' | 'huge';

/** "Within the last …" presets for the created/modified date facets. */
export type DatePreset = 'today' | 'week' | 'month' | 'year';

/**
 * User-specified media-duration bounds in **whole seconds**, mapped to a
 * `video_duration:"min..max"` clause. `null` = open-ended on that side; both ends
 * are **inclusive** (unlike the half-open SIZE_BUCKETS, which tile contiguously).
 */
export interface DurationRange {
  min: number | null;
  max: number | null;
}

/** Size-bucket bounds in bytes; `null` = open-ended on that side. */
const SIZE_BUCKETS: Record<SizeBucket, [number | null, number | null]> = {
  small: [null, 1_048_576], // < 1 MB
  medium: [1_048_576, 10_485_760], // 1–10 MB
  large: [10_485_760, 104_857_600], // 10–100 MB
  huge: [104_857_600, null], // > 100 MB
};

/** Lookback window per date preset, in days from the start of today. */
const DATE_PRESET_DAYS: Record<DatePreset, number> = {
  today: 0,
  week: 7,
  month: 30,
  year: 365,
};

/**
 * Lower-bound date for a preset, anchored to UTC midnight. Shared by the
 * server-side `created>"…"` clause and the client-side favourites matcher so the
 * two never disagree, and stable across paged fetches within a day (a per-page
 * `Date.now()` would creep forward and skip/dup items at the boundary).
 */
function sinceMidnight(preset: DatePreset, nowMs: number): Date {
  const d = new Date(nowMs);
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() - DATE_PRESET_DAYS[preset]);
  return d;
}

export interface GetFilesParams {
  folder?: string;
  recursive?: number;
  limit?: number;
  offset?: number;
  search?: string;
  q?: string;
  /** Restrict to these file-type categories (Filerobot `type:"…"` clause). */
  types?: FileTypeFilter[];
  /** Restrict to a file-size bucket (`size:"min..max"` clause). */
  sizeBucket?: SizeBucket;
  /** Restrict to a media-duration range in seconds (`video_duration:"min..max"` clause). */
  durationRange?: DurationRange;
  /** Only assets created within this window (`created>"…"` clause). */
  createdWithin?: DatePreset;
  /** Only assets modified within this window (`updated>"…"` clause). */
  updatedWithin?: DatePreset;
  sortBy?: 'created_at' | 'modified_at' | 'name' | 'size' | 'type';
  sortDirection?: 'asc' | 'desc';
  /** Additive computed fields; `cdn_permalink` must be requested explicitly. */
  fields?: string[];
}

const DEFAULT_API_FIELDS = ['cdn_permalink'];

const EXT: Record<string, AssetType> = {};
const addExt = (type: AssetType, exts: string) => exts.split(' ').forEach((e) => (EXT[e] = type));
addExt('image', 'jpg jpeg png gif webp svg avif bmp tif tiff heic ico');
addExt('video', 'mp4 webm mov m4v avi mkv ogv');
addExt('audio', 'mp3 wav ogg oga m4a aac flac');
addExt('document', 'pdf doc docx xls xlsx ppt pptx txt csv rtf md');
addExt('model', 'glb gltf obj fbx stl usdz ply 3ds dae');

function toAssetType(raw: RawFile): AssetType {
  const ext = (raw.name.split('.').pop() || '').toLowerCase();
  // 3D models usually have a generic MIME, so extension wins for them.
  if (EXT[ext] === 'model') return 'model';

  const t = (raw.file_type || raw.type || '').toLowerCase();
  if (t.startsWith('image')) return 'image';
  if (t.startsWith('video')) return 'video';
  if (t.startsWith('audio')) return 'audio';
  if (t.includes('pdf') || t.includes('document') || t.includes('text')) return 'document';

  return EXT[ext] ?? 'other';
}

function normalizeFile(raw: RawFile): Asset {
  return {
    uuid: raw.uuid,
    name: raw.name,
    folder: (typeof raw.folder === 'string' ? raw.folder : raw.folder?.name) || '/',
    type: toAssetType(raw),
    fileType: raw.file_type ?? raw.type,
    cdnUrl: raw.url?.cdn_permalink ?? raw.url?.cdn ?? raw.cdn_permalink ?? raw.cdn_url,
    thumbnailUrl:
      raw.info?.video_thumbnail ??
      raw.info?.thumbnail ??
      raw.info?.image_thumbnail ??
      raw.data?.thumbnail ??
      raw.info?.preview,
    ...(raw.visibility === undefined ? {} : { isPublic: isVisibilityPublic(raw.visibility) }),
    // Live API returns `size: { bytes, pretty }`; tolerate a plain number too.
    size: typeof raw.size === 'object' ? raw.size?.bytes : raw.size,
    duration: raw.info?.video_duration ?? raw.info?.duration,
    width: raw.width,
    height: raw.height,
    createdAt: raw.created_at,
    modifiedAt: raw.modified_at,
  };
}

function buildFilesQuery(params: GetFilesParams): Record<string, unknown> {
  const fields = params.fields ?? DEFAULT_API_FIELDS;
  const sortField = params.sortBy ?? 'created_at';
  const sortDir = params.sortDirection ?? 'desc';

  const parts: string[] = [];
  if (params.search) parts.push(params.search);
  if (params.q) parts.push(params.q);
  // Facet clauses — same notation js-admin-react-filerobot-v5 emits, space-joined.
  if (params.types?.length) parts.push(`type:${params.types.map((t) => `"${t}"`).join(',')}`);
  if (params.sizeBucket) {
    const [min, max] = SIZE_BUCKETS[params.sizeBucket];
    parts.push(`size:"${min ?? ''}..${max ?? ''}"`);
  }
  if (params.durationRange) {
    const { min, max } = params.durationRange;
    // An all-null range constrains nothing — emit no clause rather than `video_duration:".."`.
    if (min != null || max != null) parts.push(`video_duration:"${min ?? ''}..${max ?? ''}"`);
  }
  // Date facets are an after-date bound on created/updated ("Today" = since the
  // start of today, not a rolling 24h window — see sinceMidnight).
  const now = Date.now();
  if (params.createdWithin)
    parts.push(`created>"${sinceMidnight(params.createdWithin, now).toISOString()}"`);
  if (params.updatedWithin)
    parts.push(`updated>"${sinceMidnight(params.updatedWithin, now).toISOString()}"`);

  return {
    offset: params.offset ?? 0,
    limit: params.limit ?? 100,
    format: 'json,regvar:api,select:internal',
    preview: 2301, // Filerobot preview-size preset for thumbnails
    recursive: params.recursive ?? 1,
    fields: fields.length ? fields : undefined,
    sort: `${sortField}:${sortDir}`,
    folder: params.folder,
    q: parts.length ? parts.join(' ') : undefined,
  };
}

export interface FilesPage {
  assets: Asset[];
  /** Total matching the query (from the API when available, else this page's size). */
  total: number;
}

/** One page of files. `total` is the API's grand total when provided, else this page's size. */
export async function getFilesPage(
  client: DamClient,
  params: GetFilesParams = {},
): Promise<FilesPage> {
  const query = buildFilesQuery(params);
  const res = await client.get<GetFilesResponse>('/files', query);
  const assets = (res.files ?? []).map(normalizeFile);
  const total = typeof res.total === 'number' ? res.total : (res.count ?? assets.length);
  return { assets, total };
}

export async function getFiles(client: DamClient, params: GetFilesParams = {}): Promise<Asset[]> {
  return (await getFilesPage(client, params)).assets;
}

/** Subset of the facets that can also be evaluated client-side (favourites). */
export type FacetFilters = Pick<
  GetFilesParams,
  'types' | 'sizeBucket' | 'durationRange' | 'createdWithin' | 'updatedWithin'
>;

/** Our AssetType → the FileTypeFilter bucket the `type` facet selects on. */
const TYPE_TO_FILTER: Record<AssetType, FileTypeFilter> = {
  image: 'image',
  video: 'video',
  audio: 'audio',
  document: 'document',
  model: 'other', // no dedicated 'model' facet — folds into "Other"
  archive: 'other',
  font: 'other',
  other: 'other',
};

/**
 * Does an already-loaded asset satisfy the facet filters? Used for the
 * Favourites axis, which fetches a known uuid set directly and filters in
 * memory rather than re-querying the server. Mirrors buildFilesQuery's clauses
 * (shares SIZE_BUCKETS / sinceMidnight) so server- and client-side agree.
 */
export function assetMatchesFacets(asset: Asset, f: FacetFilters, nowMs: number): boolean {
  if (f.types?.length && !f.types.includes(TYPE_TO_FILTER[asset.type])) return false;
  if (f.sizeBucket) {
    const [min, max] = SIZE_BUCKETS[f.sizeBucket];
    if (asset.size == null) return false;
    if (min != null && asset.size < min) return false;
    if (max != null && asset.size >= max) return false;
  }
  if (f.durationRange) {
    const { min, max } = f.durationRange;
    // Undurated assets are excluded server-side too, so drop them here for parity.
    if (asset.duration == null) return false;
    // Inclusive on both ends — a user-entered range, not a contiguous bucket.
    if (min != null && asset.duration < min) return false;
    if (max != null && asset.duration > max) return false;
  }
  if (f.createdWithin) {
    const t = asset.createdAt ? Date.parse(asset.createdAt) : NaN;
    if (!(t >= sinceMidnight(f.createdWithin, nowMs).getTime())) return false;
  }
  if (f.updatedWithin) {
    const t = asset.modifiedAt ? Date.parse(asset.modifiedAt) : NaN;
    if (!(t >= sinceMidnight(f.updatedWithin, nowMs).getTime())) return false;
  }
  return true;
}

type SortField = NonNullable<GetFilesParams['sortBy']>;

/**
 * Client-side sort matching the server's `sort=field:dir`, for the favourites set — the same
 * order the multi-folder feed merges by (`compareAssetsBySort`), so both agree on one sort.
 */
export function sortAssets(assets: Asset[], sortBy: SortField, dir: 'asc' | 'desc'): Asset[] {
  return [...assets].sort(compareAssetsBySort(sortBy, dir, ASSET_SORT_FIELDS));
}

/**
 * Fetch specific files by uuid (one `GET /file/{uuid}` each, bounded concurrency).
 * The Favourites axis is a known, usually-small uuid set, so this is far cheaper
 * than scanning the whole library. Missing/forbidden uuids are skipped; results
 * keep the input order (caller re-sorts as needed).
 */
export async function getFilesByUuids(
  client: DamClient,
  uuids: string[],
  opts: { concurrency?: number; fields?: string[] } = {},
): Promise<Asset[]> {
  const fields = opts.fields ?? DEFAULT_API_FIELDS;
  const out: Array<Asset | undefined> = new Array(uuids.length);
  let next = 0;
  const worker = async (): Promise<void> => {
    while (next < uuids.length) {
      const i = next++;
      try {
        const res = await client.get<{ file?: RawFile }>(`/file/${encodeURIComponent(uuids[i])}`, {
          format: 'json,regvar:api,select:internal',
          preview: 2301,
          fields: fields.length ? fields : undefined,
        });
        if (res?.file) out[i] = normalizeFile(res.file);
      } catch {
        /* a deleted/forbidden favourite just drops out of the list */
      }
    }
  };
  const lanes = Math.min(opts.concurrency ?? 8, uuids.length);
  await Promise.all(Array.from({ length: lanes }, worker));
  return out.filter((a): a is Asset => a !== undefined);
}

// ── light-dam's management layer ─────────────────────────────────────────────
// Endpoint shapes verified against js-admin-react-filerobot-v5
// (src/features/files/files.service.ts): rename is per-file; delete and move are
// bulk (uuid arrays in the body). The leading path segment is singular `/file`
// for rename, plural `/files` for the bulk operations — matching the backend.

export async function renameFile(client: DamClient, uuid: string, newName: string): Promise<void> {
  const res = await client.put<ApiStatusResponse>(`/file/${encodeURIComponent(uuid)}/name`, {
    name: newName,
  });
  if (res?.status === 'error') throw new Error(res.msg || 'Failed to rename file');
}

export async function deleteFiles(client: DamClient, uuids: string[]): Promise<void> {
  const res = await client.delete<ApiStatusResponse>('/files', { files_uuids: uuids });
  if (res?.status === 'error') throw new Error(res.msg || 'Failed to delete files');
}

export async function moveFiles(
  client: DamClient,
  uuids: string[],
  destinationFolder: string,
): Promise<void> {
  const res = await client.post<ApiStatusResponse>('/files', {
    files_uuids: uuids,
    new_folder_name: destinationFolder,
  });
  if (res?.status === 'error') throw new Error(res.msg || 'Failed to move files');
}
