import type { SortDirection } from '../store/browse-store';
import type { Asset } from '../types/asset.types';

/** The least an asset must carry to be fed: the feed de-duplicates by `uuid`. */
export interface FeedAsset {
  uuid: string;
}

/**
 * The raw Filerobot file fields `compareAssetsBySort` reads by default. They are required (as on
 * `FilerobotAsset`) so that an asset in another shape — camelCase dates, a numeric `size` — is a
 * type error rather than a list that silently sorts as all-equal: such assets go through
 * `AssetSortFields` instead (`ASSET_SORT_FIELDS` for dam-core's normalized `Asset`).
 */
export interface SortableAsset extends FeedAsset {
  name: string;
  type: string;
  size: { bytes?: number };
  created_at: string;
  modified_at: string;
}

/** `folder.name` is the file's own folder path — what `splitByFolder` places a file by. */
export interface FolderPlacedAsset extends FeedAsset {
  folder?: { name?: string };
}

/** Reads the folder path a file lives in — see `splitByFolder`. */
export type AssetFolderOf<A> = (asset: A) => string | undefined;

/** Where `compareAssetsBySort` reads each sort field from; a missing value sorts as empty or 0. */
export interface AssetSortFields<A> {
  name(asset: A): string | undefined;
  /** The MIME string — the server sorts `type` by it (`application/pdf` < `image/png`). */
  mimeType(asset: A): string | undefined;
  bytes(asset: A): number | undefined;
  createdAt(asset: A): string | undefined;
  modifiedAt(asset: A): string | undefined;
}

/** Sort fields of a raw Filerobot file (`FilerobotAsset`) — `compareAssetsBySort`'s default. */
export const RAW_FILE_SORT_FIELDS: AssetSortFields<SortableAsset> = {
  name: (a) => a.name,
  mimeType: (a) => a.type,
  bytes: (a) => a.size?.bytes,
  createdAt: (a) => a.created_at,
  modifiedAt: (a) => a.modified_at,
};

/** Sort fields of dam-core's normalized `Asset` (as held by `BrowseStore`). */
export const ASSET_SORT_FIELDS: AssetSortFields<Asset> = {
  name: (a) => a.name,
  mimeType: (a) => a.fileType,
  bytes: (a) => a.size,
  createdAt: (a) => a.createdAt,
  modifiedAt: (a) => a.modifiedAt,
};

/** Sort keys `compareAssetsBySort` orders by a field, matching the server. */
export type ComparableSortKey =
  | 'name'
  | 'size'
  | 'type'
  | 'created_at'
  | 'uploaded'
  | 'modified_at'
  | 'updated_at';

/**
 * Sort keys the API accepts that have no field comparable across folders. `relevance` scores are
 * computed per request, the rest aren't on the file — every pair ties and the feed interleaves.
 */
export type UnorderedSortKey =
  | 'relevance'
  | 'title'
  | 'color'
  | 'files_count_recursive'
  | 'files_size_recursive';

/** Every sort key `compareAssetsBySort` knows — a closed list, so a typo is a type error. */
export type FeedSortKey = ComparableSortKey | UnorderedSortKey;

/** Fetches one page of a single folder's (recursive) listing, already filtered and sorted. */
export type FetchFolderPage<A extends FeedAsset = FeedAsset> = (
  folder: string,
  offset: number,
  limit: number,
) => Promise<A[]>;

export type AssetComparator<A extends FeedAsset = FeedAsset> = (a: A, b: A) => number;

/** Fetches the same page window of several folders at once, as one page per requested folder. */
export type FetchFoldersPage<A extends FeedAsset = FeedAsset> = (
  folders: string[],
  offset: number,
  limit: number,
) => Promise<Map<string, A[]>>;

/**
 * A `FetchFolderPage` that coalesces the calls made in the same tick for the same window
 * (`offset` + `limit`) into one `fetchMany` request — `MultiFolderFeed` asks for every drained
 * folder at once, so the first page of N folders becomes one request instead of N. This relies on
 * the multi-folder `QUERY /files` applying `limit`/`offset` and the sort to each folder on its
 * own, so each folder's share is exactly its `GET /files` page (PROD v2610.08.01, 2026-10-08). A
 * window asked for by a single folder, a failed batch, or one that misses a folder or gives one
 * more than `limit`, goes through `fetchOne` per folder.
 */
export function batchFolderPages<A extends FeedAsset>(
  fetchMany: FetchFoldersPage<A>,
  fetchOne: FetchFolderPage<A>,
): FetchFolderPage<A> {
  type Call = { folder: string; resolve: (a: A[]) => void; reject: (e: unknown) => void };
  let windows: Map<string, Call[]> | null = null;

  const flush = (pending: Map<string, Call[]>) => {
    for (const [key, calls] of pending) {
      const [offset, limit] = JSON.parse(key) as [number, number];
      const single = (call: Call) =>
        fetchOne(call.folder, offset, limit).then(call.resolve, call.reject);
      if (calls.length === 1) {
        single(calls[0]);
        continue;
      }
      fetchMany(
        calls.map((c) => c.folder),
        offset,
        limit,
      ).then(
        (pages) => {
          // More than `limit` for a folder means the backend didn't page per folder (older
          // releases ignored limit/offset/q here) — such a page can't be trusted.
          const usable = calls.every((c) => (pages.get(c.folder)?.length ?? Infinity) <= limit);
          if (usable) {
            calls.forEach((c) => c.resolve(pages.get(c.folder)!));
          } else {
            calls.forEach(single);
          }
        },
        () => calls.forEach(single),
      );
    }
  };

  return (folder, offset, limit) =>
    new Promise<A[]>((resolve, reject) => {
      if (!windows) {
        const pending = new Map<string, Call[]>();
        windows = pending;
        queueMicrotask(() => {
          windows = null;
          flush(pending);
        });
      }
      const key = JSON.stringify([offset, limit]);
      const calls = windows.get(key) ?? [];
      calls.push({ folder, resolve, reject });
      windows.set(key, calls);
    });
}

/** `file.folder.name` — read defensively, so a file in another shape is unplaceable, not a throw. */
const rawFileFolder: AssetFolderOf<FeedAsset> = (file) => {
  const name = (file as FolderPlacedAsset).folder?.name;
  return typeof name === 'string' ? name : undefined;
};

/**
 * Split a multi-folder page by the requested folder each file lives under — the file's own
 * folder (`file.folder.name` on a raw file, or what `folderOf` returns), which may be a subfolder
 * of it. Paths match case-sensitively, like the API (`/portals` and `/Portals` are different
 * folders). Folders must not overlap — see `dedupeOverlappingFolderPaths`. `null` when a file
 * can't be placed: dropping it would lose it and make its folder's page look short, i.e. the
 * folder ended.
 */
export function splitByFolder<A extends FolderPlacedAsset>(
  files: A[],
  folders: string[],
): Map<string, A[]> | null;
export function splitByFolder<A extends FeedAsset>(
  files: A[],
  folders: string[],
  folderOf: AssetFolderOf<A>,
): Map<string, A[]> | null;
export function splitByFolder<A extends FeedAsset>(
  files: A[],
  folders: string[],
  folderOf: AssetFolderOf<A> = rawFileFolder,
): Map<string, A[]> | null {
  const pages = new Map(folders.map((folder) => [folder, [] as A[]]));
  const roots = folders.map((folder) => ({ folder, prefix: folder.replace(/\/+$/, '') }));
  for (const file of files) {
    const path = folderOf(file);
    if (!path) return null;
    const owner = roots.find(({ prefix }) => path === prefix || path.startsWith(`${prefix}/`));
    if (!owner) return null;
    pages.get(owner.folder)!.push(file);
  }
  return pages;
}

// The backend orders names like an ICU collation that ignores case and punctuation
// (`ic-dropbox` sorts before `ic-drop`). Checked live against PROD elastic_v3 (v2609.29.03) on
// 1,219 adjacent pairs: this collator disagreed on one (`case-studies` vs `Case+Study+…`); plain
// `localeCompare` disagreed on 58. Built on first use, so importing dam-core costs nothing.
let nameCollator: Intl.Collator | undefined;
const getNameCollator = () =>
  (nameCollator ??= new Intl.Collator('en', { sensitivity: 'base', ignorePunctuation: true }));

const time = (iso: string | undefined): number => (iso ? Date.parse(iso) || 0 : 0);

type AscendingOrder = <A extends FeedAsset>(fields: AssetSortFields<A>) => AssetComparator<A>;

/**
 * The ascending order of every `FeedSortKey`, `null` for keys with no comparable field. A
 * `Record`, so a key added to `FeedSortKey` and left out here fails to compile.
 */
const ASCENDING_ORDER: Record<FeedSortKey, AscendingOrder | null> = {
  name: (f) => (a, b) => getNameCollator().compare(f.name(a) ?? '', f.name(b) ?? ''),
  size: (f) => (a, b) => (f.bytes(a) ?? 0) - (f.bytes(b) ?? 0),
  type: (f) => (a, b) => (f.mimeType(a) ?? '').localeCompare(f.mimeType(b) ?? ''),
  modified_at: (f) => (a, b) => time(f.modifiedAt(a)) - time(f.modifiedAt(b)),
  updated_at: (f) => (a, b) => time(f.modifiedAt(a)) - time(f.modifiedAt(b)),
  created_at: (f) => (a, b) => time(f.createdAt(a)) - time(f.createdAt(b)),
  uploaded: (f) => (a, b) => time(f.createdAt(a)) - time(f.createdAt(b)),
  relevance: null,
  title: null,
  color: null,
  files_count_recursive: null,
  files_size_recursive: null,
};

function comparatorFor<A extends FeedAsset>(
  sortBy: FeedSortKey,
  direction: SortDirection,
  fields: AssetSortFields<A>,
): AssetComparator<A> {
  // `hasOwn` so an untyped key (`toString`…) from a JS host can't reach the prototype.
  const order = Object.hasOwn(ASCENDING_ORDER, sortBy) ? ASCENDING_ORDER[sortBy] : null;
  if (!order) return () => 0;
  const ascending = order(fields);
  return direction === 'asc' ? ascending : (a, b) => ascending(b, a);
}

/**
 * Client-side order matching what the server applied for `sort=<sortBy>:<direction>`, so that
 * per-folder pages already sorted by the server merge into one correctly ordered list.
 *
 * Fields are read from a raw Filerobot file unless `fields` says otherwise (`ASSET_SORT_FIELDS`
 * for dam-core's `Asset`). An `UnorderedSortKey` (`relevance`, `title`…) returns 0 for every
 * pair — ties are broken by the feed instead. So does a key outside `FeedSortKey` reaching here
 * untyped, rather than throwing mid-scroll.
 */
export function compareAssetsBySort<A extends SortableAsset>(
  sortBy: FeedSortKey,
  direction: SortDirection,
): AssetComparator<A>;
export function compareAssetsBySort<A extends FeedAsset>(
  sortBy: FeedSortKey,
  direction: SortDirection,
  fields: AssetSortFields<A>,
): AssetComparator<A>;
export function compareAssetsBySort<A extends FeedAsset>(
  sortBy: FeedSortKey,
  direction: SortDirection,
  fields?: AssetSortFields<A>,
): AssetComparator<A> | AssetComparator<SortableAsset> {
  return fields
    ? comparatorFor(sortBy, direction, fields)
    : comparatorFor(sortBy, direction, RAW_FILE_SORT_FIELDS);
}

/**
 * Everything fetched so far for ONE folder under ONE query (filters + search + sort). Append-only,
 * so several feeds can read it — which is what lets a cached folder be reused when another folder
 * is added to or removed from the selection (see `FolderListingCache`).
 */
export class FolderListing<A extends FeedAsset = FeedAsset> {
  readonly items: A[] = [];
  exhausted = false;
  private nextOffset = 0;
  private pending: Promise<void> | null = null;

  constructor(
    readonly folder: string,
    private readonly fetchPage: FetchFolderPage<A>,
    readonly pageSize: number,
  ) {}

  /** Fetch the next page. Concurrent callers share one request; a failure can be retried. */
  loadMore(): Promise<void> {
    if (this.exhausted) return Promise.resolve();
    if (!this.pending) {
      this.pending = (async () => {
        const page = await this.fetchPage(this.folder, this.nextOffset, this.pageSize);
        // Same paging contract as the single-folder view: the window advances by the requested
        // size and a short page ends the folder.
        this.nextOffset += this.pageSize;
        if (page.length < this.pageSize) this.exhausted = true;
        this.items.push(...page);
      })().finally(() => {
        this.pending = null;
      });
    }
    return this.pending;
  }
}

/**
 * Per-folder listings keyed by folder + query, so changing only the folder selection re-fetches
 * nothing but the newly added folder. Any other change (a filter, the search, the sort) yields a
 * different query key and so fresh listings. Clear it whenever the library itself may have
 * changed (picker reopened, upload finished, project switched).
 *
 * The key doesn't see `fetchPage` (callers build a new one per load), so `queryKey` must identify
 * everything that decides the result — including the project or credentials when one cache can
 * outlive them; otherwise call `clear()` on the switch. A reused listing keeps paging with the
 * fetcher it was created with, so all of its pages come from one source.
 *
 * Bounded (least recently used out): every search term or filter change adds a listing per
 * folder, and an inline picker may live for the whole page session without ever reopening.
 */
export class FolderListingCache<A extends FeedAsset = FeedAsset> {
  private readonly listings = new Map<string, FolderListing<A>>();

  constructor(private readonly maxEntries = 30) {}

  get(
    folder: string,
    queryKey: string,
    fetchPage: FetchFolderPage<A>,
    pageSize: number,
  ): FolderListing<A> {
    const key = JSON.stringify([folder, queryKey, pageSize]);
    let listing = this.listings.get(key);
    if (listing) {
      // Re-insert to mark it most recently used (Map keeps insertion order).
      this.listings.delete(key);
    } else {
      listing = new FolderListing(folder, fetchPage, pageSize);
    }
    this.listings.set(key, listing);
    while (this.listings.size > this.maxEntries) {
      this.listings.delete(this.listings.keys().next().value!);
    }
    return listing;
  }

  get size(): number {
    return this.listings.size;
  }

  clear(): void {
    this.listings.clear();
  }
}

interface FeedCursor<A extends FeedAsset> {
  listing: FolderListing<A>;
  /** Next unread index into `listing.items`. */
  pos: number;
  /** How many assets this folder has contributed — the tie-breaker (see `next`). */
  taken: number;
}

/**
 * An infinite-scroll feed over several folders at once.
 *
 * The Filerobot API has no request that pages several folders in one sort order (`q=folders:` is
 * rejected; `QUERY /files` + `folders_uuids` sorts and pages each folder on its own and returns
 * them one after another), so each folder is paged on its own and the pages are k-way merged by
 * the same order the server sorted them in. Each folder is only fetched when everything already
 * loaded for it has been read, so deep scrolling costs about one request per folder that ran out —
 * unlike refetching every folder from offset 0. Folders that run out together can share one
 * request (`batchFolderPages`).
 *
 * Folders must not overlap (see `dedupeOverlappingFolderPaths`); assets are still de-duplicated
 * by uuid as a safety net.
 */
export class MultiFolderFeed<A extends FeedAsset = FeedAsset> {
  private readonly cursors: FeedCursor<A>[];
  private readonly seen = new Set<string>();
  /** Tail of the `next()` queue — calls run one at a time (see `next`). */
  private queue: Promise<unknown> = Promise.resolve();

  constructor(
    listings: FolderListing<A>[],
    private readonly compare: AssetComparator<A>,
  ) {
    this.cursors = listings.map((listing) => ({ listing, pos: 0, taken: 0 }));
  }

  get hasMore(): boolean {
    return this.cursors.some((c) => c.pos < c.listing.items.length || !c.listing.exhausted);
  }

  /**
   * Up to `count` more assets, in merged order. Fewer means the feed ran out — or that a fetch
   * failed after some assets were already taken: those are returned rather than dropped, and the
   * failed page is retried by the next call. It only throws when it could take nothing at all.
   *
   * Calls are queued, so an infinite-scroll page and a "select all" drain can't interleave on
   * the shared cursors and split the assets between them.
   */
  next(count: number): Promise<A[]> {
    const run = this.queue.then(() => this.take(count));
    this.queue = run.catch(() => undefined);
    return run;
  }

  private async take(count: number): Promise<A[]> {
    const out: A[] = [];
    while (out.length < count) {
      // Every live folder needs a head before the smallest one can be picked.
      try {
        await this.loadDrainedFolders();
      } catch (error) {
        if (out.length > 0) return out;
        throw error;
      }

      let best: FeedCursor<A> | null = null;
      for (const cursor of this.cursors) {
        if (cursor.pos >= cursor.listing.items.length) continue;
        if (!best) {
          best = cursor;
          continue;
        }
        const order = this.compare(cursor.listing.items[cursor.pos], best.listing.items[best.pos]);
        // On a tie the folder that has given the least goes first, so equal keys — and
        // `relevance`, which is all ties — interleave the folders instead of draining one.
        if (order < 0 || (order === 0 && cursor.taken < best.taken)) best = cursor;
      }
      if (!best) break;

      const asset = best.listing.items[best.pos++];
      best.taken++;
      if (this.seen.has(asset.uuid)) continue;
      this.seen.add(asset.uuid);
      out.push(asset);
    }
    return out;
  }

  private async loadDrainedFolders(): Promise<void> {
    const drained = this.cursors.filter(
      (c) => c.pos >= c.listing.items.length && !c.listing.exhausted,
    );
    if (drained.length === 0) return;
    await Promise.all(drained.map((c) => c.listing.loadMore()));
  }
}
