import { customElement } from '../utils/define-element';
import { SfxTooltipBase } from './sfx-tooltip-base';

/**
 * `<sfx-tooltip>` — {@link SfxTooltipBase} registered under its public tag.
 *
 * Importing this module registers the tag globally. Libraries that only need the behaviour under
 * their own tag (e.g. dam-metadata's `sfx-meta-hint-tooltip`) should extend `SfxTooltipBase` from
 * `@scaleflex/dam-ui/primitives/sfx-tooltip-base` instead, so they don't claim `sfx-tooltip` away
 * from other libraries on the page that ship their own (the Hub's annotator does).
 */
@customElement('sfx-tooltip')
export class SfxTooltip extends SfxTooltipBase {}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-tooltip': SfxTooltip;
  }
}
