import { LitElement, html, css, nothing } from 'lit';
import { property } from 'lit/decorators.js';
import { customElement } from '../utils/define-element';

/** One label/value pair in an asset details list (e.g. "Size" → "1.4 MB"). */
export interface AssetInfoRow {
  label: string;
  value: string;
  /** Tooltip / full text when the value is truncated (defaults to `value`). */
  title?: string;
}

/**
 * `<sfx-asset-info>` — the shared "File info" details block: a heading over a
 * label/value list, optionally collapsible. View-model driven (it takes plain
 * `rows`, never an Asset), so every DAM widget feeds it from its own asset shape
 * and lays it out inside its own panel/sidebar. Themed via the canonical
 * `--sfx-*` tokens (with sensible fallbacks).
 */
@customElement('sfx-asset-info')
export class SfxAssetInfo extends LitElement {
  static styles = css`
    :host {
      display: block;
      font-family: var(--sfx-font-family, system-ui, -apple-system, sans-serif);
    }
    .head {
      display: flex;
      align-items: center;
      gap: 8px;
      width: 100%;
      margin: 0;
      padding: 0;
      background: none;
      border: none;
      font: inherit;
      font-weight: 600;
      color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
      text-align: left;
    }
    button.head {
      cursor: pointer;
    }
    .head .spacer {
      flex: 1;
    }
    .chevron {
      width: 16px;
      height: 16px;
      flex: 0 0 auto;
      color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
      transition: transform 0.15s ease;
    }
    :host([open]) .chevron {
      transform: rotate(180deg);
    }
    dl {
      display: grid;
      grid-template-columns: 92px 1fr;
      gap: 9px 10px;
      margin: 12px 0 0;
      font-size: 13px;
    }
    dt {
      color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
    }
    dd {
      margin: 0;
      color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  `;

  /** Section title shown above the rows. */
  @property() heading = 'File info';
  /** The label/value pairs to render. */
  @property({ attribute: false }) rows: AssetInfoRow[] = [];
  /** When true the heading toggles the list open/closed. */
  @property({ type: Boolean }) collapsible = false;
  /** Expanded state (reflected so `:host([open])` can style the chevron). */
  @property({ type: Boolean, reflect: true }) open = true;

  private toggle(): void {
    if (this.collapsible) this.open = !this.open;
  }

  private renderHead() {
    const label = html`<span>${this.heading}</span><span class="spacer"></span>`;
    if (!this.collapsible) return html`<div class="head">${label}</div>`;
    return html`<button
      class="head"
      type="button"
      aria-expanded=${this.open ? 'true' : 'false'}
      @click=${() => this.toggle()}
    >
      ${label}
      <svg class="chevron" viewBox="0 0 24 24" fill="none" aria-hidden="true">
        <path
          d="m6 9 6 6 6-6"
          stroke="currentColor"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      </svg>
    </button>`;
  }

  render() {
    return html`
      ${this.renderHead()}
      ${this.open
        ? html`<dl>
            ${this.rows.map(
              (r) =>
                html`<dt>${r.label}</dt>
                  <dd title=${r.title ?? r.value}>${r.value}</dd>`,
            )}
          </dl>`
        : nothing}
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-asset-info': SfxAssetInfo;
  }
}
