/** Generic fallback icon (last resort for the <img> error cascade). */
/** @deprecated Use `getFileTypeIconUrl()` (no name returns the generic icon). */
export function getDefaultFileTypeIconUrl(): string {
  return FILE_TYPES_AND_ICONS._default;
}

/** MIME types whose subtype isn't the icon's extension. Others use the subtype (`image/png`). */
const MIME_EXTENSIONS: Record<string, string> = {
  'image/svg+xml': 'svg',
  'image/vnd.adobe.photoshop': 'psd',
  'video/quicktime': 'mp4',
  'video/x-msvideo': 'avi',
  'audio/mpeg': 'mp3',
  'audio/x-wav': 'wav',
  'audio/wave': 'wav',
  'audio/ogg': 'oga',
  'video/ogg': 'ogv',
  'application/msword': 'doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.ms-excel': 'xls',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/vnd.ms-powerpoint': 'ppt',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'application/vnd.oasis.opendocument.text': 'odt',
  'application/vnd.oasis.opendocument.spreadsheet': 'ods',
  'application/vnd.oasis.opendocument.presentation': 'odp',
  'application/epub+zip': 'epub',
  'application/x-zip-compressed': 'zip',
  'application/x-7z-compressed': '7z',
  'application/x-rar-compressed': 'rar',
  'application/vnd.rar': 'rar',
  'application/gzip': 'gz',
  'application/x-tar': 'tar',
  'application/ld+json': 'jsonld',
  'application/xhtml+xml': 'xhtml',
  'text/plain': 'txt',
  'text/javascript': 'js',
  'application/javascript': 'js',
  'text/calendar': 'ics',
  'font/sfnt': 'ttf',
};

/** The icon extension for a full MIME type (`''` for none, or for the API's short `image`). */
function extensionFromMime(mime: string | undefined): string {
  const type = (mime ?? '').split(';')[0].trim().toLowerCase();
  if (!type.includes('/')) return '';
  return MIME_EXTENSIONS[type] ?? type.split('/')[1];
}

/**
 * Hosted file-type icon URL for a file name (or bare extension). The extension decides first
 * (icons are per extension, and MIME types are often generic, e.g. `application/octet-stream` for
 * `.psd`); when it has no icon (or the name has no extension), `mime` decides
 * (`'Brochure'` + `application/pdf` → the PDF icon). Returns the **generic** icon when neither
 * maps, or when nothing is given (`getFileTypeIconUrl()`), which is the last step of an `<img>`
 * error cascade.
 */
export function getFileTypeIconUrl(name?: string, mime?: string): string {
  const ext = (name?.split('.').pop() || '').toLowerCase();
  return (
    FILE_TYPES_AND_ICONS[ext] ||
    FILE_TYPES_AND_ICONS[extensionFromMime(mime)] ||
    FILE_TYPES_AND_ICONS._default
  );
}
