// @scaleflex/dam-core — signing the URLs a widget renders itself (display URLs).
//
// Widgets render files from `<token>.filerobot.com`, never from the container's CNAME (host pages'
// CSPs allow `*.filerobot.com` but not every customer domain), and show non-public files by
// appending their SASS key. The key must
// only go to the container it belongs to, must follow key refreshes, must never reach URLs the
// host app stores, and several widgets (several containers) can live on one page. This module is
// the one implementation of that policy, shared by asset-picker and light-dam.

import { formatToCdnUrl, signCdnUrl } from './filerobot-url';
import { FILEROBOT_DOMAIN } from './filerobot-url.constants';

/**
 * Whether a Filerobot visibility value means "public in the CDN": the v5 Files API object
 * (`visibility.in_cdn.actual` starting with `public`) or a plain visibility string. Anything else,
 * including a missing value, is not public.
 */
export function isVisibilityPublic(visibility: unknown): boolean {
  const actual =
    typeof visibility === 'string'
      ? visibility
      : (visibility as { in_cdn?: { actual?: unknown } } | null | undefined)?.in_cdn?.actual;
  return typeof actual === 'string' && actual.startsWith('public');
}

/** A SASS key, or a getter that returns the current one (so key refreshes are picked up). */
export type SecretKeySource = string | null | undefined | (() => string | null | undefined);

/** One widget instance's display-signing setup, see {@link registerDisplaySigning}. */
export interface DisplaySigningRegistration {
  /** The container the key belongs to. Only this container's URLs are signed with it. */
  containerToken: string;
  /** The container's CNAME host, when known up front. */
  containerCdn?: string | null;
  /**
   * The SASS key, or a getter returning the current key. Omit it (or pass `null`) when the widget
   * mustn't sign, e.g. security-template (guest) mode: the registration then only lets
   * {@link formatToDisplayUrl} move the container's CNAME onto its token host.
   */
  secretKey?: SecretKeySource;
}

const registrations: DisplaySigningRegistration[] = [];

/**
 * Register a widget instance's SASS key for {@link signDisplayUrl}. Call it once the key is known
 * and call the returned function when the instance goes away (or re-initialises), so the key
 * doesn't outlive it. Pass a getter when the key can be refreshed (e.g. `() => client.authKey`).
 *
 * Registrations are per container: two widgets for two containers on one page each sign their own
 * container's URLs with their own key. For the same container the latest registration wins.
 */
export function registerDisplaySigning(registration: DisplaySigningRegistration): () => void {
  const entry = { ...registration };
  registrations.push(entry);
  return () => {
    const index = registrations.indexOf(entry);
    if (index >= 0) registrations.splice(index, 1);
  };
}

/** Options for {@link formatToDisplayUrl}. */
export interface FormatToDisplayUrlOptions {
  /**
   * The container CNAME the URL may be on, e.g. derived from the asset's own CDN URL. Used when
   * the registration doesn't know its CNAME; ignored if several containers are registered.
   */
  containerCdn?: string | null;
}

/** Options for {@link signDisplayUrl}. */
export interface SignDisplayUrlOptions extends FormatToDisplayUrlOptions {
  /** The file is public in the CDN: nothing to sign. `undefined` (unknown) is signed. */
  isPublic?: boolean;
}

function resolveKey(source: SecretKeySource | undefined): string | null {
  const key = typeof source === 'function' ? source() : source;
  return key || null;
}

/**
 * `.internal` files (API thumbnails, previews, video posters) are served without `secret_key`,
 * non-public files included (verified 2026-11-09), so display URLs on that path are never signed.
 */
function isInternalPath(url: string): boolean {
  return /^https?:\/\/[^/?#]+\/\.internal\//i.test(url);
}

function hostOf(url: string): string | null {
  const match = /^https?:\/\/([^/?#]+)/i.exec(url);
  return match ? match[1].toLowerCase() : null;
}

function findRegistration(
  host: string,
  hintCdn: string | null | undefined,
): { registration: DisplaySigningRegistration; containerCdn: string | null } | null {
  for (let i = registrations.length - 1; i >= 0; i--) {
    const registration = registrations[i];
    if (host === `${registration.containerToken.toLowerCase()}.${FILEROBOT_DOMAIN}`) {
      return { registration, containerCdn: registration.containerCdn ?? null };
    }
    if (registration.containerCdn && host === registration.containerCdn.toLowerCase()) {
      return { registration, containerCdn: registration.containerCdn };
    }
  }
  // A CNAME the registration didn't know: only safe to attribute when one container is registered.
  const tokens = new Set(registrations.map((r) => r.containerToken));
  if (hintCdn && host === hintCdn.toLowerCase() && tokens.size === 1) {
    return { registration: registrations[registrations.length - 1], containerCdn: hintCdn };
  }
  return null;
}

/**
 * Prepare a URL a widget renders itself (thumbnail, preview image): append the SASS key of the
 * container the URL belongs to, so a non-public file loads from the customer CDN. Returns the
 * URL unchanged when the file is public, for `.internal` files (served unsigned), when no
 * registered container owns the URL (another
 * container, an external host, the preview proxy), or when no key is available.
 *
 * Only for URLs rendered in the widget's own DOM. Never sign URLs handed to the host app (they
 * get stored and published, and the key is short-lived), and never sign URLs passed to host code
 * such as a URL-rewriting callback.
 */
export function signDisplayUrl(url: string, options: SignDisplayUrlOptions = {}): string {
  if (!url || options.isPublic || isInternalPath(url)) return url ?? '';
  const host = hostOf(url);
  if (!host) return url;
  const found = findRegistration(host, options.containerCdn);
  if (!found) return url;
  // `findRegistration` already matched the outer host to this container; narrowing by token again
  // would judge a nest by its inner URL (a CNAME the registration may not know yet).
  return signCdnUrl(url, resolveKey(found.registration.secretKey), {
    containerCdn: found.containerCdn,
  });
}

/**
 * Prepare a URL a widget renders itself (`<img>`, `<video>`, `<audio>`, poster, iframe): when a
 * registered container owns it, a URL on that container's CNAME moves to
 * `<containerToken>.filerobot.com` (the host page's CSP may not allow the customer's domain; the
 * token host serves the same files). One job, the host move: chain {@link signDisplayUrl} to sign
 * a non-public file — `signDisplayUrl(formatToDisplayUrl(url), { isPublic })`. URLs no registered
 * container owns are returned unchanged.
 *
 * `options.containerCdn` is a CNAME hint, e.g. the host of the file's own `url.cdn` when it isn't
 * a Filerobot host; it is only used when exactly one container is registered, so the move works
 * before `/public/settings` has answered.
 *
 * Only for URLs rendered in the widget's own DOM. URLs handed to the host app keep their host.
 */
export function formatToDisplayUrl(url: string, options: FormatToDisplayUrlOptions = {}): string {
  if (!url) return url ?? '';
  const host = hostOf(url);
  if (!host) return url;
  const found = findRegistration(host, options.containerCdn);
  if (!found) return url;
  return formatToCdnUrl(url, {
    containerToken: found.registration.containerToken,
    containerCdn: found.containerCdn,
  });
}

/**
 * One widget instance's display-signing lifecycle, so widgets don't hand-roll register /
 * unregister logic. Framework-free: call it from a Lit/React/whatever lifecycle.
 *
 * - `start()` begins a (re)bootstrap, drops the current registration and returns a ticket; pass it to `set()` once the key (and
 *   the CNAME from `/public/settings`) is known. A newer `start()` invalidates older tickets, so a
 *   slow bootstrap can't overwrite a newer one.
 * - `set(ticket, registration | null)` replaces this instance's registration (`null` = don't sign,
 *   e.g. security-template / guest mode). Ignored for a stale ticket. While disconnected it is
 *   only remembered, and registered on the next `connect()` — so a bootstrap that resolves after
 *   the element was removed never leaves a key registered.
 * - `connect()` / `disconnect()` follow the element: register the remembered registration /
 *   unregister it.
 */
export interface DisplaySigningHandle {
  start(): number;
  set(ticket: number, registration: DisplaySigningRegistration | null): void;
  connect(): void;
  disconnect(): void;
}

/** Create a {@link DisplaySigningHandle} for one widget instance (starts connected). */
export function createDisplaySigning(): DisplaySigningHandle {
  let ticket = 0;
  let connected = true;
  let registration: DisplaySigningRegistration | null = null;
  let unregister: (() => void) | null = null;

  const apply = () => {
    unregister?.();
    unregister = connected && registration ? registerDisplaySigning(registration) : null;
  };

  return {
    start: () => {
      // A new bootstrap drops the previous registration right away, so a bootstrap that fails
      // before set() can't leave the old container's key signing.
      registration = null;
      apply();
      return ++ticket;
    },
    set(forTicket, next) {
      if (forTicket !== ticket) return;
      registration = next;
      apply();
    },
    connect() {
      connected = true;
      apply();
    },
    disconnect() {
      connected = false;
      apply();
    },
  };
}
