// @scaleflex/dam-core — CDN transform helpers (resize / format / quality / download).
// `getTransformParams` maps transform options onto CDN params. Callers apply them to the layer they
// choose: `setUrlParams(url, params)` on a plain URL, or a wrapper layer around a preset with
// `setCdnParams(url, [{ p }, params], ctx)` (next to `p=` the CDN ignores sizing params, see
// ~/Documentation/filerobot-url-handling.md §7).
import { formatToCdnUrl, getCdnParams, parseFilerobotUrl, setCdnParams } from './filerobot-url';
import { setUrlParams, type CdnParams } from './url-params';

// ── transformed download / embed (mirrors js-admin-react-filerobot-v5) ─────────

/** Output formats the transform pipeline supports. */
export type DownloadFormat = 'webp' | 'jpeg' | 'png' | 'gif';

/** Quality presets → numeric `q` (JPEG/WEBP), matching the reference admin. */
export const QUALITY_LEVELS = { excellent: 90, good: 75, fair: 60 } as const;
export type QualityLevel = keyof typeof QUALITY_LEVELS;

/** Standardized resize presets (max box, in px); "Full HD" + the reference's large/medium/small. */
export const RESIZE_PRESETS = { fullhd: 1920, large: 1200, medium: 600, small: 300 } as const;
export type ResizePreset = keyof typeof RESIZE_PRESETS;

/** Animated formats need the dual cloudimage token so the still + animated paths both work. */
const FORMAT_TO_CLOUDIMG: Partial<Record<DownloadFormat, string>> = {
  webp: 'awebp,webp',
  gif: 'agif,gif',
};

/** How width/height are applied: `bound` fits inside the box, `cover` fills it (may crop). */
export type TransformFit = 'bound' | 'cover';

/** Options for {@link getTransformParams}. */
export interface TransformOptions {
  /** Output format → `force_format` (`webp` / `gif` use the animated pair, e.g. `awebp,webp`). */
  format?: DownloadFormat;
  /**
   * Numeric `q` (1–100). Use QUALITY_LEVELS for the named presets. Omit for "Original" quality.
   * Ignored for `png` (lossless).
   */
  quality?: number;
  width?: number;
  height?: number;
  /**
   * How width/height are applied (only with a width or height): `bound` fits inside the box and
   * keeps the ratio, `cover` fills the box and may crop. Omit to leave `func` off.
   */
  fit?: TransformFit;
  /** Never upscale past the source (`org_if_sml=1`; only with a width or height). */
  noUpscale?: boolean;
  /**
   * Serve as a download attachment named after this file name, with the extension swapped for
   * `format` (`force_download=<name>`). `download=1` is dropped: it bypasses transforms.
   */
  downloadAs?: string;
}

/**
 * The CDN params for a transform: `w`, `h`, `q` (not for PNG), `force_format`, `func`,
 * `org_if_sml` and, with `downloadAs`, `force_download=<name with the new extension>`. Only the
 * options that are set produce a param; when any does, `download: null` is added too, because
 * `download=1` bypasses transforms. Apply them with `setUrlParams(url, getTransformParams(t))`.
 */
export function getTransformParams(t: TransformOptions): CdnParams {
  const params: CdnParams = {};
  const sized = !!(t.width || t.height);
  if (t.width) params.w = t.width;
  if (t.height) params.h = t.height;
  if (t.quality != null && t.format !== 'png') params.q = t.quality;
  if (t.format) params.force_format = FORMAT_TO_CLOUDIMG[t.format] ?? t.format;
  if (t.fit && sized) params.func = t.fit;
  if (t.noUpscale && sized) params.org_if_sml = 1;
  if (t.downloadAs) params.force_download = transformedFileName(t.downloadAs, t.format);
  if (Object.keys(params).length) params.download = null;
  return params;
}

/** The downloaded file's name with the new extension (jpeg → jpg) when reformatting. */
export function transformedFileName(originalName: string, format?: DownloadFormat): string {
  if (!format) return originalName;
  const ext = format === 'jpeg' ? 'jpg' : format;
  // Strip the trailing extension, but never reduce to an empty base (".htaccess").
  const base = originalName.replace(/\.[^./\\]+$/, '') || originalName;
  return `${base}.${ext}`;
}

/**
 * Build a CDN URL that serves the *transformed* asset as a download attachment.
 *
 * @deprecated Use `setUrlParams(url, getTransformParams({ ...t, downloadAs: originalName }))`, or
 * `setCdnParams(url, [{}, params], ctx)` to apply it to a preset's result.
 */
export function buildTransformedDownloadUrl(
  cdnUrl: string,
  originalName: string,
  t: TransformOptions = {},
): string {
  return legacyTransform(cdnUrl, { ...t, downloadAs: originalName });
}

/**
 * Build a CDN URL for the transformed asset for embedding/linking (no download flag).
 *
 * @deprecated Use `setUrlParams(url, getTransformParams(t))`, or
 * `setCdnParams(url, [{}, params], ctx)` to apply it to a preset's result.
 */
export function buildEmbedUrl(cdnUrl: string, t: TransformOptions = {}): string {
  return legacyTransform(cdnUrl, t);
}

// The deprecated builders keep their 0.7.0 output: they move the host, drop `download=1`, and put
// the transform on a new wrapper around the whole URL when any layer carries a preset (on the URL's
// own container), so it applies to the preset's result even when `p=` sits on a wrapper.
function legacyTransform(cdnUrl: string, t: TransformOptions): string {
  const base = formatToCdnUrl(cdnUrl, {});
  const params = getTransformParams(t);
  if (!Object.keys(params).length) return setUrlParams(base, { download: null });
  const ctx = { containerToken: parseFilerobotUrl(base, {})?.token ?? null };
  const layers = getCdnParams(base, ctx);
  if (!layers.some((layer) => layer.p)) return setUrlParams(base, params);
  const changes: CdnParams[] = layers.map(() => ({}));
  changes[0] = { download: null };
  changes.push(params);
  return setCdnParams(base, changes, ctx);
}
