// @scaleflex/dam-core — query-param editing shared by every URL helper.

/** A single CDN query-param value. See {@link CdnParams} for how each kind is applied. */
export type CdnParamValue = string | number | boolean | null | undefined;

/**
 * Extra Cloudimage / Filerobot CDN query params, keyed by their raw names from the CDN docs
 * (`w`, `h`, `q`, `func`, `force_format`, `doc_page`, `org_if_sml`, `ci_url_encoded`, …).
 *
 * How {@link setUrlParams} applies each value:
 * - string / number → set (replaces an existing value, never duplicates the key)
 * - `true` → `1`
 * - `false`, `null`, `undefined` → the key is removed (e.g. `{ func: null }` strips `func=proxy`)
 *
 * @example { w: 400, func: 'bound', force_format: 'webp,jpeg' }
 */
export type CdnParams = Record<string, CdnParamValue>;

/**
 * The only params allowed on a preset's layer (`p=` itself and the file version `vh`). Next to a
 * preset, any other param is ignored when the preset defines it and applied when it doesn't
 * (`width` / `height` even replace the preset), verified 2026-11-10 against preset definitions on
 * `fbmjmuoeb`: a preset's definition can't be read client-side, so the result is unpredictable.
 * Everything else belongs on a wrapper layer around the preset. Shared with `fixCdnParams`.
 *
 * @internal
 */
export const PRESET_LAYER_PARAMS: readonly string[] = ['vh', 'p'];

/**
 * Query params that aren't transformations and never count as "next to a preset": the wrapper's own
 * `ci_url_encoded` and the signing `secret_key`.
 *
 * @internal
 */
export const NON_TRANSFORM_PARAMS: readonly string[] = ['ci_url_encoded', 'secret_key'];

let presetParamsWarned = false;

/** @internal Test hook: re-arm the once-per-process preset warning. */
export function resetPresetParamsWarning(): void {
  presetParamsWarned = false;
}

/** Scaleflex CDN hosts (as `isFilerobotCdnHost`; kept here to avoid an import cycle). */
const SCALEFLEX_CDN_HOST_RE = /(^|\.)(filerobot\.com|filerobot\.io|cloudimg\.io)$/i;

function warnIfPresetParamsIgnored(params: URLSearchParams, hostname: string): void {
  if (presetParamsWarned || !params.get('p') || !SCALEFLEX_CDN_HOST_RE.test(hostname)) return;
  const others = [...new Set(params.keys())].filter(
    (key) => !PRESET_LAYER_PARAMS.includes(key) && !NON_TRANSFORM_PARAMS.includes(key),
  );
  if (!others.length) return;
  presetParamsWarned = true;
  console.warn(
    `[dam-core] setUrlParams(): a preset (p=) is set together with ${others.join(', ')}. Only vh ` +
      'may sit next to a preset: other params are ignored or applied depending on how the preset ' +
      'is defined (width / height even replace it). Put them on a wrapper layer: ' +
      'setCdnParams(url, [{ p, vh }, params], ctx), or repair the URL with ' +
      'fixCdnParamsUrl(url, ctx). (Shown once.)',
  );
}

/**
 * Set or remove query params on an absolute http(s) URL — the one param editor every dam-core
 * URL helper goes through.
 *
 * Never throws: an empty, relative, unparseable or inline (`data:` / `blob:`) URL is returned
 * unchanged. When no param actually changes, the input string is returned as-is (byte for
 * byte), so a no-op never re-encodes the URL.
 *
 * Logs a `console.warn` (once per process) when the result carries a preset (`p=`) together with
 * any other param except `vh` (the CDN's result is then preset-dependent): put those on a wrapper
 * layer with `setCdnParams` instead.
 *
 * @example
 * setUrlParams('https://tkn.filerobot.com/a.jpg?func=proxy', { w: 400, func: null })
 * // → 'https://tkn.filerobot.com/a.jpg?w=400'
 */
export function setUrlParams(url: string, cdnParams: CdnParams): string {
  if (!url) return url ?? '';

  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return url;
  }
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') return url;

  let changed = false;
  for (const [key, value] of Object.entries(cdnParams)) {
    if (value === null || value === undefined || value === false) {
      if (parsed.searchParams.has(key)) {
        parsed.searchParams.delete(key);
        changed = true;
      }
      continue;
    }

    const next = value === true ? '1' : String(value);
    const current = parsed.searchParams.getAll(key);
    if (current.length !== 1 || current[0] !== next) {
      parsed.searchParams.set(key, next);
      changed = true;
    }
  }

  if (!changed) return url;
  warnIfPresetParamsIgnored(parsed.searchParams, parsed.hostname);
  return parsed.toString();
}

/**
 * Whether a source carries its bytes inline (`data:` / `blob:`). Such sources have no CDN to
 * ask for a resized copy, and appending query params corrupts them (for a `data:image/svg+xml`
 * URI the `?w=…` tail lands inside the SVG payload). Every dam-core URL helper passes them
 * through unchanged.
 */
export function isInlineUrl(url: string): boolean {
  return url.startsWith('data:') || url.startsWith('blob:');
}
