import { LitElement, html, css, type PropertyValues } from 'lit';
import { property, query } from 'lit/decorators.js';
import { ifDefined } from 'lit/directives/if-defined.js';

/** Gap between the trigger and the tip, and the minimum distance kept from viewport edges. */
const GAP = 6;
const EDGE = 4;

const supportsPopover = (): boolean =>
  typeof HTMLElement !== 'undefined' &&
  Object.prototype.hasOwnProperty.call(HTMLElement.prototype, 'popover');

/**
 * Hover tooltip around the slotted trigger.
 *
 * - Default: a single-line tip absolutely positioned inside the host, shown on `:hover`.
 * - `multiline`: lets long text wrap (max 280px) — for admin-written help texts.
 * - `floating`: renders the tip in the browser top layer (Popover API) with `position: fixed`
 *   coordinates, so it escapes `overflow` clipping of scroll containers and stacks above modal
 *   dialogs. Also opens on keyboard focus (`:focus-visible`) and closes on Escape / scroll.
 *   Falls back to the default CSS-hover tip where the Popover API is unavailable.
 */
export class SfxTooltipBase extends LitElement {
  static styles = [
    css`
      :host {
        position: relative;
        display: inline-flex;
      }
      .tip {
        display: none;
        position: absolute;
        bottom: calc(100% + 6px);
        left: 50%;
        transform: translateX(-50%);
        white-space: nowrap;
        /* Theming hooks — defaults are the original dark tip. Set them on the host (or an
           ancestor) to restyle, e.g. dam-metadata's light field-hint tooltip. */
        padding: var(--sfx-tooltip-padding, 4px 8px);
        font-size: var(--sfx-tooltip-font-size, 0.75rem);
        font-weight: 400;
        background: var(--sfx-tooltip-bg, var(--sfx-foreground, oklch(0.37 0.022 248.413)));
        color: var(--sfx-tooltip-fg, var(--sfx-background, oklch(1 0 0)));
        border-radius: var(--sfx-tooltip-radius, 4px);
        box-shadow: var(--sfx-tooltip-shadow, none);
        pointer-events: none;
        z-index: 100;
      }
      .tip.bottom {
        bottom: auto;
        top: calc(100% + 6px);
      }
      :host(:hover) .tip:not(.popover) {
        display: block;
      }
      :host([multiline]) .tip {
        white-space: normal;
        width: max-content;
        max-width: var(--sfx-tooltip-max-width, 280px);
        text-align: start;
        line-height: var(--sfx-tooltip-line-height, 1.4);
        overflow-wrap: anywhere;
      }
      /* Top-layer tip: neutralise the UA popover styles; coordinates are set from JS. */
      .tip.popover {
        position: fixed;
        inset: auto;
        margin: 0;
        border: 0;
        transform: none;
        overflow: visible;
      }
      .tip.popover:popover-open {
        display: block;
      }
    `,
  ];

  @property() text = '';
  /** Which side of the trigger the tip opens on (default `top`; use `bottom` near the
   *  viewport's top edge, e.g. toolbar buttons). In `floating` mode this is a preference —
   *  the tip flips when there is no room on that side. */
  @property() placement: 'top' | 'bottom' = 'top';
  /** Let long text wrap (max 280px wide) instead of staying on one line. */
  @property({ type: Boolean, reflect: true }) multiline = false;
  /** Render in the top layer so the tip is never clipped by scroll containers or modals. */
  @property({ type: Boolean, reflect: true }) floating = false;

  /** `null` until first render. The `!` is Lit's `@query` idiom — an initializer would
   *  assign to the decorator's getter-only accessor under legacy decorators and throw. */
  @query('.tip') private _tip!: HTMLElement | null;

  private get _usePopover(): boolean {
    return this.floating && supportsPopover();
  }

  connectedCallback(): void {
    super.connectedCallback();
    this.addEventListener('mouseenter', this._onEnter);
    this.addEventListener('mouseleave', this._onMouseLeave);
    this.addEventListener('focusin', this._onFocusIn);
    this.addEventListener('focusout', this._onFocusOut);
    this.addEventListener('keydown', this._onKeyDown);
  }

  disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('mouseenter', this._onEnter);
    this.removeEventListener('mouseleave', this._onMouseLeave);
    this.removeEventListener('focusin', this._onFocusIn);
    this.removeEventListener('focusout', this._onFocusOut);
    this.removeEventListener('keydown', this._onKeyDown);
    this.hide();
  }

  /** Open the floating tip (no-op unless `floating` and the Popover API is available). */
  show(): void {
    const tip = this._tip;
    if (!this._usePopover || !tip || !this.text) return;
    if (!this._open) {
      tip.showPopover();
      this._open = true;
      this._listenForScroll(true);
    }
    this._position(tip);
  }

  /** Close the floating tip. */
  hide(): void {
    if (!this._open) return;
    this._open = false;
    this._listenForScroll(false);
    try {
      this._tip?.hidePopover();
    } catch {
      /* already closed (e.g. light-dismissed) */
    }
  }

  /** Whether the floating tip is currently shown. */
  get open(): boolean {
    return this._open;
  }

  private _open = false;
  /** Every shadow root between the host and the document, captured when the tip opens. */
  private _scrollRoots: Array<Document | ShadowRoot> = [];

  /** Pointer currently over the host — keeps a blur from closing a tip the user is hovering. */
  private _hovered = false;
  /** Keyboard focus currently inside the host — keeps a mouseleave from closing a focused tip. */
  private _focused = false;

  private _onEnter = (): void => {
    this._hovered = true;
    this.show();
  };
  private _onMouseLeave = (): void => {
    this._hovered = false;
    if (!this._focused) this.hide();
  };
  private _onFocusOut = (e: FocusEvent): void => {
    if (e.relatedTarget instanceof Node && this.contains(e.relatedTarget)) return;
    this._focused = false;
    if (!this._hovered) this.hide();
  };
  private _onScroll = (): void => this.hide();

  protected updated(changed: PropertyValues<this>): void {
    super.updated(changed);
    if (!changed.has('text') || !this._open) return;
    // The tip's size depends on its text: re-measure, or close it if there's nothing to show.
    if (!this.text) this.hide();
    else if (this._tip) this._position(this._tip);
  }

  /**
   * The tip sits at fixed viewport coordinates, so any scroll that moves the trigger must close
   * it. `scroll` is not composed: a listener on `window` never sees a scroll container living
   * inside a shadow root (the bulk field list, the uploader form). So listen (capture) on each
   * enclosing root, plus the composed `wheel` / `touchmove` on `window` as a catch-all.
   */
  private _listenForScroll(on: boolean): void {
    if (on) this._scrollRoots = this._enclosingRoots();
    const opts: AddEventListenerOptions = { capture: true, passive: true };
    const targets: Array<[EventTarget, string]> = [
      ...this._scrollRoots.map((r): [EventTarget, string] => [r, 'scroll']),
      [window, 'scroll'],
      [window, 'wheel'],
      [window, 'touchmove'],
    ];
    for (const [target, type] of targets) {
      if (on) target.addEventListener(type, this._onScroll, opts);
      else target.removeEventListener(type, this._onScroll, opts);
    }
    if (!on) this._scrollRoots = [];
  }

  /** Shadow roots from the host outwards, then the document. */
  private _enclosingRoots(): Array<Document | ShadowRoot> {
    const roots: Array<Document | ShadowRoot> = [];
    let root = this.getRootNode();
    while (root instanceof ShadowRoot) {
      roots.push(root);
      root = root.host.getRootNode();
    }
    if (root instanceof Document) roots.push(root);
    return roots;
  }

  private _onFocusIn = (e: FocusEvent): void => {
    const target = e.target as Element | null;
    // Keyboard focus only — a mouse click focusing the trigger shouldn't pin the tip open.
    let focusVisible = true;
    try {
      focusVisible = !!target?.matches(':focus-visible');
    } catch {
      /* selector unsupported — treat as visible */
    }
    if (!focusVisible) return;
    this._focused = true;
    this.show();
  };

  private _onKeyDown = (e: KeyboardEvent): void => {
    if (e.key !== 'Escape' || !this._open) return;
    // Close only the tip: stopPropagation keeps document-level Escape handlers (e.g. the bulk
    // modal's close flow) from firing; preventDefault stops a native modal <dialog> from
    // treating it as a cancel request.
    e.preventDefault();
    e.stopPropagation();
    this.hide();
  };

  private _position(tip: HTMLElement): void {
    const host = this.getBoundingClientRect();
    const tipRect = tip.getBoundingClientRect();
    const vw = window.innerWidth || document.documentElement.clientWidth;
    const vh = window.innerHeight || document.documentElement.clientHeight;

    const above = host.top - GAP - tipRect.height;
    const below = host.bottom + GAP;
    const fitsAbove = above >= EDGE;
    const fitsBelow = below + tipRect.height <= vh - EDGE;
    const top =
      this.placement === 'bottom'
        ? fitsBelow || !fitsAbove
          ? below
          : above
        : fitsAbove || !fitsBelow
          ? above
          : below;

    const centered = host.left + host.width / 2 - tipRect.width / 2;
    const left = Math.max(EDGE, Math.min(centered, vw - tipRect.width - EDGE));

    tip.style.top = `${Math.max(EDGE, top)}px`;
    tip.style.left = `${left}px`;
  }

  render() {
    const usePopover = this._usePopover;
    const cls = ['tip', this.placement === 'bottom' ? 'bottom' : '', usePopover ? 'popover' : '']
      .filter(Boolean)
      .join(' ');
    return html`
      <slot></slot>
      <div class=${cls} role="tooltip" popover=${ifDefined(usePopover ? 'manual' : undefined)}>
        ${this.text}
      </div>
    `;
  }
}
