// Framework-free state for a lazy folder tree: what is loaded, what is expanded,
// what is in flight, and the current search. Mirrors the getState/subscribe/set triad
// used by dam-core's BrowseStore so the same Lit controller bridges either one.
//
// Beyond BrowseStore's tree slice this adds three things it cannot express:
//   • per-node status, so "page 1 of 3 loaded" ('partial') is distinguishable from "loaded"
//   • reveal(path) — expand every ancestor of a deep path in one shot
//   • search with supersede guards (plus an abort signal offered to sources that can use
//     it — the built-in API source cannot; see SearchOptions.signal)
//
// Every async entry point is guarded by a monotonic sequence number so a slow response
// can never overwrite a newer one.

import type { Folder } from '@scaleflex/dam-core';
import type { FolderSource } from './folder-source';

export type NodeStatus = 'idle' | 'loading' | 'loaded' | 'partial' | 'error';
export type SearchStatus = 'idle' | 'loading' | 'done' | 'error';

export interface SearchState {
  query: string;
  status: SearchStatus;
  results: Folder[];
  /** Results hit the server limit — more matches exist. */
  truncated: boolean;
}

export interface FolderTreeState {
  /** path → its loaded children (possibly a prefix of them; see nodeStatus). */
  children: Readonly<Record<string, Folder[]>>;
  nodeStatus: Readonly<Record<string, NodeStatus>>;
  expanded: ReadonlySet<string>;
  search: SearchState;
  /** Last non-recoverable error, for the host to surface. */
  error?: string;
}

export interface FolderTreeStoreOptions {
  source: FolderSource;
  rootPath?: string;
  /** Children fetched per request. */
  pageSize?: number;
  /** How many pages to chase automatically before parking the node as 'partial'. */
  maxAutoPages?: number;
  searchLimit?: number;
}

type Listener = (state: FolderTreeState) => void;

const DEFAULT_PAGE_SIZE = 200;
const DEFAULT_MAX_AUTO_PAGES = 10;
const DEFAULT_SEARCH_LIMIT = 500;

const EMPTY_SEARCH: SearchState = { query: '', status: 'idle', results: [], truncated: false };

/** Parent of a path: "/a/b" → "/a", "/a" → "/". */
export function parentOf(path: string): string {
  return path.replace(/\/[^/]*$/, '') || '/';
}

/**
 * Every ancestor of `path` below `rootPath`, root-first and including `path` itself.
 * `/a/b/c` under `/` → `['/', '/a', '/a/b', '/a/b/c']`.
 */
export function ancestorChain(path: string, rootPath = '/'): string[] {
  const normalizedRoot = rootPath.replace(/\/+$/, '') || '/';
  if (path === normalizedRoot) return [normalizedRoot];

  const prefix = normalizedRoot === '/' ? '/' : `${normalizedRoot}/`;
  if (!path.startsWith(prefix)) return [normalizedRoot];

  const rest = path.slice(prefix.length).split('/').filter(Boolean);
  const chain = [normalizedRoot];
  let current = normalizedRoot === '/' ? '' : normalizedRoot;
  for (const segment of rest) {
    current = `${current}/${segment}`;
    chain.push(current);
  }
  return chain;
}

/** Stable order for merged pages — the server's order is not guaranteed across them. */
function sortFolders(folders: Folder[]): Folder[] {
  return [...folders].sort((a, b) => a.name.localeCompare(b.name));
}

export class FolderTreeStore {
  private source: FolderSource;
  private readonly rootPath: string;
  private readonly pageSize: number;
  private readonly maxAutoPages: number;
  private readonly searchLimit: number;

  private state: FolderTreeState = {
    children: {},
    nodeStatus: {},
    expanded: new Set(),
    search: EMPTY_SEARCH,
  };

  private readonly listeners = new Set<Listener>();

  /** Per-path load sequence — a superseded load must not write its result. */
  private readonly loadSeq = new Map<string, number>();
  private searchSeq = 0;
  private revealSeq = 0;
  private searchAbort?: AbortController;

  constructor(options: FolderTreeStoreOptions) {
    this.source = options.source;
    this.rootPath = options.rootPath?.replace(/\/+$/, '') || '/';
    this.pageSize = options.pageSize ?? DEFAULT_PAGE_SIZE;
    this.maxAutoPages = options.maxAutoPages ?? DEFAULT_MAX_AUTO_PAGES;
    this.searchLimit = options.searchLimit ?? DEFAULT_SEARCH_LIMIT;
  }

  getState(): FolderTreeState {
    return this.state;
  }

  /**
   * Point the store at a different data layer while keeping what is already loaded and
   * expanded. Rebuilding the store instead would collapse the whole tree, which is what
   * a React host re-rendering with a fresh `source` object identity used to trigger on
   * every render. In-flight loads are superseded so their results cannot land as if they
   * had come from the new source, and the root is re-read to pick up genuine changes.
   */
  async setSource(source: FolderSource): Promise<void> {
    if (source === this.source) return;
    this.source = source;
    this.searchAbort?.abort();
    this.searchAbort = undefined;
    this.searchSeq += 1;
    for (const path of this.loadSeq.keys()) this.nextSeq(path);
    await this.loadChildren(this.rootPath, { force: true });
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private set(patch: Partial<FolderTreeState>): void {
    this.state = { ...this.state, ...patch };
    for (const listener of this.listeners) listener(this.state);
  }

  private setStatus(path: string, status: NodeStatus): void {
    this.set({ nodeStatus: { ...this.state.nodeStatus, [path]: status } });
  }

  /**
   * `error` is an aggregate — "something is currently broken" — so it must retire once
   * nothing is broken any more. Leaving it set after a successful retry stranded hosts
   * with a stale banner and, because the element de-duplicates by message, silently
   * swallowed the *next* identical failure. Keyed on live status rather than cleared on
   * every success, so one node succeeding cannot mask another node that is still failing.
   */
  private errorAfter(nodeStatus: Record<string, NodeStatus>, search = this.state.search): string | undefined {
    const failing =
      Object.values(nodeStatus).some((s) => s === 'error') || search.status === 'error';
    return failing ? this.state.error : undefined;
  }

  private nextSeq(path: string): number {
    const seq = (this.loadSeq.get(path) ?? 0) + 1;
    this.loadSeq.set(path, seq);
    return seq;
  }

  // ── loading ───────────────────────────────────────────────────────────────

  /**
   * Fetch a node's children. Cached by default — pass `force` to refetch (used to
   * reconcile after an optimistic create).
   */
  async loadChildren(path: string, opts: { force?: boolean } = {}): Promise<void> {
    const status = this.state.nodeStatus[path];
    if (!opts.force && (status === 'loading' || status === 'loaded' || status === 'partial')) {
      return;
    }

    const seq = this.nextSeq(path);
    this.setStatus(path, 'loading');

    try {
      const { folders, exhausted } = await this.fetchPages(path, 0);
      if (seq !== this.loadSeq.get(path)) return;

      const nodeStatus: Record<string, NodeStatus> = {
        ...this.state.nodeStatus,
        [path]: exhausted ? 'loaded' : 'partial',
      };
      this.set({
        children: { ...this.state.children, [path]: sortFolders(folders) },
        nodeStatus,
        error: this.errorAfter(nodeStatus),
      });
    } catch (error) {
      if (seq !== this.loadSeq.get(path)) return;
      // Leave any previously cached children in place — a failed refresh must not
      // blank out a node the user is looking at.
      this.set({
        nodeStatus: { ...this.state.nodeStatus, [path]: 'error' },
        error: messageOf(error),
      });
    }
  }

  /** Continue a node parked at 'partial'. */
  async loadMore(path: string): Promise<void> {
    if (this.state.nodeStatus[path] !== 'partial') return;

    const seq = this.nextSeq(path);
    const known = this.state.children[path] ?? [];
    this.setStatus(path, 'loading');

    try {
      const { folders, exhausted } = await this.fetchPages(path, known.length);
      if (seq !== this.loadSeq.get(path)) return;

      const nodeStatus: Record<string, NodeStatus> = {
        ...this.state.nodeStatus,
        [path]: exhausted ? 'loaded' : 'partial',
      };
      this.set({
        children: { ...this.state.children, [path]: sortFolders([...known, ...folders]) },
        nodeStatus,
        error: this.errorAfter(nodeStatus),
      });
    } catch (error) {
      if (seq !== this.loadSeq.get(path)) return;
      this.set({
        nodeStatus: { ...this.state.nodeStatus, [path]: 'partial' },
        error: messageOf(error),
      });
    }
  }

  /**
   * Chase pages from `offset` until the server returns a short page or we hit
   * `maxAutoPages`. `exhausted` false means the node still has more to give.
   */
  private async fetchPages(
    path: string,
    offset: number,
  ): Promise<{ folders: Folder[]; exhausted: boolean }> {
    const collected: Folder[] = [];
    let cursor = offset;

    for (let page = 0; page < this.maxAutoPages; page += 1) {
      const result = await this.source.listChildren(path, {
        offset: cursor,
        limit: this.pageSize,
      });
      collected.push(...result.folders);
      cursor += result.folders.length;
      if (!result.hasMore) return { folders: collected, exhausted: true };
    }

    return { folders: collected, exhausted: false };
  }

  // ── expansion ─────────────────────────────────────────────────────────────

  /** Fold the whole tree back up. What is loaded stays loaded — only expansion is reset. */
  collapseAll(): void {
    if (!this.state.expanded.size) return;
    this.set({ expanded: new Set() });
  }

  async toggle(path: string): Promise<void> {
    const expanded = new Set(this.state.expanded);
    if (expanded.has(path)) {
      expanded.delete(path);
      this.set({ expanded });
      return;
    }

    expanded.add(path);
    this.set({ expanded });
    await this.loadChildren(path);
  }

  /**
   * Expand every ancestor of `path` and load their children. Ancestors are fetched in
   * parallel — the API is keyed by path, not by parent id, so no sequencing is needed.
   */
  async reveal(path: string): Promise<void> {
    const seq = (this.revealSeq += 1);
    const chain = ancestorChain(path, this.rootPath);
    // The target itself is expanded only if the user opens it; its ancestors must be.
    const toExpand = chain.slice(0, -1);

    await Promise.all(chain.map((p) => this.loadChildren(p)));
    if (seq !== this.revealSeq) return;

    const expanded = new Set(this.state.expanded);
    for (const p of toExpand) expanded.add(p);
    this.set({ expanded });
  }

  // ── search ────────────────────────────────────────────────────────────────

  /** Clears results and returns the tree view. Does not hit the network. */
  clearSearch(): void {
    this.searchAbort?.abort();
    this.searchAbort = undefined;
    this.searchSeq += 1;
    this.set({ search: EMPTY_SEARCH });
  }

  async runSearch(query: string): Promise<void> {
    const trimmed = query.trim();
    if (!trimmed) {
      this.clearSearch();
      return;
    }
    if (!this.source.search) return;

    this.searchAbort?.abort();
    const abort = new AbortController();
    this.searchAbort = abort;
    const seq = (this.searchSeq += 1);

    this.set({ search: { ...this.state.search, query: trimmed, status: 'loading' } });

    try {
      const results = await this.source.search(trimmed, {
        rootPath: this.rootPath,
        limit: this.searchLimit,
        signal: abort.signal,
      });
      if (seq !== this.searchSeq) return;

      const search: SearchState = {
        query: trimmed,
        status: 'done',
        results,
        truncated: results.length === this.searchLimit,
      };
      this.set({ search, error: this.errorAfter(this.state.nodeStatus, search) });
    } catch (error) {
      if (seq !== this.searchSeq) return;
      this.set({
        search: { query: trimmed, status: 'error', results: [], truncated: false },
        error: messageOf(error),
      });
    }
  }

  // ── mutation ──────────────────────────────────────────────────────────────

  /**
   * Create a folder and insert it optimistically, then reconcile against the server in
   * the background (which heals any server-side name normalization). Returns the
   * optimistic folder so the caller can select it immediately.
   */
  async createFolder(leafName: string, parentPath: string): Promise<Folder> {
    if (!this.source.create) throw new Error('This folder source does not support creation');

    const created = await this.source.create(leafName, parentPath);
    const parent = parentPath.replace(/\/+$/, '') || '/';
    const folder: Folder =
      created ??
      ({
        uuid: '',
        name: leafName,
        path: parent === '/' ? `/${leafName}` : `${parent}/${leafName}`,
        parentPath: parent,
      } satisfies Folder);

    const siblings = this.state.children[parent] ?? [];
    const expanded = new Set(this.state.expanded);
    expanded.add(parent);

    this.set({
      children: { ...this.state.children, [parent]: sortFolders([...siblings, folder]) },
      nodeStatus: {
        ...this.state.nodeStatus,
        [parent]: this.state.nodeStatus[parent] === 'partial' ? 'partial' : 'loaded',
      },
      expanded,
    });

    void this.loadChildren(parent, { force: true });
    return folder;
  }

  /** Force-refresh specific nodes, or every node currently loaded. */
  async refresh(paths?: string[]): Promise<void> {
    const targets = paths ?? Object.keys(this.state.children);
    await Promise.all(targets.map((path) => this.loadChildren(path, { force: true })));
  }
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
