import { LitElement, html, css } from 'lit';
import { property, state } from 'lit/decorators.js';
import { resetStyles, focusStyles } from '../styles/reset';
import { customElement } from '../utils/define-element';
import type { DropdownOption } from './sfx-dropdown';
import './sfx-dropdown';
import './sfx-icon';

function startOfDay(d: Date): Date {
  const c = new Date(d);
  c.setHours(0, 0, 0, 0);
  return c;
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/**
 * Single-month calendar grid: month/year dropdown navigation, Monday-first weekday
 * row, and a day grid with today/selected/disabled states. Reproduces the hub's
 * `@scaleflex/ui-tw` Calendar design as a framework-agnostic Lit primitive.
 *
 * Range filtering (start/end) is composed by consumers from two independent
 * `sfx-calendar`/`sfx-date-input` instances cross-linked via `minDate`/`maxDate`,
 * mirroring the hub's own approach — this component has no built-in range mode.
 */
@customElement('sfx-calendar')
export class SfxCalendar extends LitElement {
  static styles = [
    resetStyles,
    focusStyles,
    css`
      :host {
        display: block;
        width: 264px;
        font-family: inherit;
      }
      .header {
        display: flex;
        align-items: center;
        gap: 2px;
        margin-bottom: 8px;
      }
      .nav-btn {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 28px;
        height: 28px;
        flex-shrink: 0;
        border: none;
        border-radius: var(--sfx-radius-sm, 6px);
        background: none;
        color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
        cursor: pointer;
      }
      .nav-btn:hover {
        background: var(--sfx-muted, oklch(0.974 0.006 239.819));
      }
      .month-select,
      .year-select {
        flex: 1;
        min-width: 0;
      }
      .weekdays {
        display: grid;
        grid-template-columns: repeat(7, 1fr);
        margin-bottom: 4px;
      }
      .weekday {
        display: flex;
        align-items: center;
        justify-content: center;
        height: 28px;
        font-size: 0.75rem;
        font-weight: 500;
        color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
      }
      .days {
        display: grid;
        grid-template-columns: repeat(7, 1fr);
        gap: 2px;
      }
      .day {
        display: flex;
        align-items: center;
        justify-content: center;
        aspect-ratio: 1;
        border: none;
        border-radius: 9999px;
        background: none;
        font-size: var(--sfx-font-size-sm, 0.875rem);
        font-family: inherit;
        color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
        cursor: pointer;
      }
      .day:hover:not(:disabled) {
        background: var(--sfx-muted, oklch(0.974 0.006 239.819));
      }
      .day.outside {
        color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
      }
      .day.today {
        background: var(--sfx-selection-bg, oklch(0.578 0.198 268.129 / 0.08));
        color: var(--sfx-primary, oklch(0.578 0.198 268.129));
        font-weight: 500;
      }
      .day.selected,
      .day.selected.today {
        background: var(--sfx-primary, oklch(0.578 0.198 268.129));
        color: var(--sfx-primary-foreground, oklch(1 0 0));
        font-weight: 500;
      }
      .day:disabled {
        color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
        opacity: 0.4;
        cursor: default;
      }
    `,
  ];

  @property({ attribute: false }) value: Date | null = null;
  @property({ attribute: false }) minDate: Date | null = null;
  @property({ attribute: false }) maxDate: Date | null = null;
  @property() locale = '';

  @state() private _viewYear = 0;
  @state() private _viewMonth = 0;
  private _viewInitialized = false;

  // Lit sets bound properties (e.g. `.value=${date}`) after construction but
  // before the first update, so initializing the view here — rather than in
  // the constructor, where `this.value` is still its class-field default —
  // correctly opens on the month of an already-selected date.
  protected willUpdate() {
    if (!this._viewInitialized) {
      this._viewInitialized = true;
      const base = this.value ?? new Date();
      this._viewYear = base.getFullYear();
      this._viewMonth = base.getMonth();
    }
  }

  private get _locale(): string {
    return this.locale || document.documentElement.lang || 'en';
  }

  private get _monthOptions(): DropdownOption[] {
    const fmt = new Intl.DateTimeFormat(this._locale, { month: 'long' });
    return Array.from({ length: 12 }, (_, i) => ({
      value: String(i),
      label: fmt.format(new Date(2000, i, 1)),
    }));
  }

  private get _yearOptions(): DropdownOption[] {
    const minY = this.minDate?.getFullYear() ?? this._viewYear - 10;
    const maxY = this.maxDate?.getFullYear() ?? this._viewYear + 10;
    return Array.from({ length: maxY - minY + 1 }, (_, i) => {
      const y = minY + i;
      return { value: String(y), label: String(y) };
    });
  }

  private get _weekdayLabels(): string[] {
    const fmt = new Intl.DateTimeFormat(this._locale, { weekday: 'short' });
    // 2000-01-03 is a Monday — anchor for a Monday-first week.
    return Array.from({ length: 7 }, (_, i) => {
      const label = fmt.format(new Date(2000, 0, 3 + i)).slice(0, 2);
      return label.charAt(0).toUpperCase() + label.slice(1);
    });
  }

  private get _days(): { date: Date; outside: boolean }[] {
    const firstOfMonth = new Date(this._viewYear, this._viewMonth, 1);
    const mondayFirstOffset = (firstOfMonth.getDay() + 6) % 7;
    const gridStart = new Date(this._viewYear, this._viewMonth, 1 - mondayFirstOffset);
    return Array.from({ length: 42 }, (_, i) => {
      const date = new Date(gridStart.getFullYear(), gridStart.getMonth(), gridStart.getDate() + i);
      return { date, outside: date.getMonth() !== this._viewMonth };
    });
  }

  private _isDisabled(d: Date): boolean {
    if (this.minDate && startOfDay(d) < startOfDay(this.minDate)) return true;
    if (this.maxDate && startOfDay(d) > startOfDay(this.maxDate)) return true;
    return false;
  }

  private _prevMonth() {
    if (this._viewMonth === 0) {
      this._viewMonth = 11;
      this._viewYear -= 1;
    } else {
      this._viewMonth -= 1;
    }
  }

  private _nextMonth() {
    if (this._viewMonth === 11) {
      this._viewMonth = 0;
      this._viewYear += 1;
    } else {
      this._viewMonth += 1;
    }
  }

  private _selectDay(date: Date) {
    if (this._isDisabled(date)) return;
    this.dispatchEvent(
      new CustomEvent('sfx-select', { detail: { date }, bubbles: true, composed: true }),
    );
  }

  render() {
    const today = startOfDay(new Date());
    return html`
      <div class="header">
        <button class="nav-btn" aria-label="Previous month" @click=${() => this._prevMonth()}>
          <sfx-icon name="chevron-left" .size=${16}></sfx-icon>
        </button>
        <sfx-dropdown
          class="month-select"
          variant="borderless"
          .options=${this._monthOptions}
          .value=${String(this._viewMonth)}
          @sfx-change=${(e: CustomEvent) => {
            this._viewMonth = Number(e.detail.value);
          }}
        ></sfx-dropdown>
        <sfx-dropdown
          class="year-select"
          variant="borderless"
          .options=${this._yearOptions}
          .value=${String(this._viewYear)}
          @sfx-change=${(e: CustomEvent) => {
            this._viewYear = Number(e.detail.value);
          }}
        ></sfx-dropdown>
        <button class="nav-btn" aria-label="Next month" @click=${() => this._nextMonth()}>
          <sfx-icon name="chevron-right" .size=${16}></sfx-icon>
        </button>
      </div>
      <div class="weekdays">
        ${this._weekdayLabels.map((w) => html`<span class="weekday">${w}</span>`)}
      </div>
      <div class="days">
        ${this._days.map(({ date, outside }) => {
          const disabled = this._isDisabled(date);
          const isToday = isSameDay(date, today);
          const isSelected = this.value ? isSameDay(date, this.value) : false;
          const classes = [
            'day',
            outside && 'outside',
            isToday && 'today',
            isSelected && 'selected',
          ]
            .filter(Boolean)
            .join(' ');
          return html`
            <button class=${classes} ?disabled=${disabled} @click=${() => this._selectDay(date)}>
              ${date.getDate()}
            </button>
          `;
        })}
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-calendar': SfxCalendar;
  }
}
