// @scaleflex/dam-core — file presentation: which URL to render for a file.
//
// The one file-level helper in dam-core (everything else is URL-level). Apps map their own file
// shape onto the flat `FilePresentationInput` (`mapToFilePresentationInput` covers the raw Files API
// object and the normalised `Asset`) and get back the URLs to render. Replaces Portals'
// `getFilerobotFilePresentation`, asset-picker's thumbnail builders and core's old `assets.`
// thumbnail helper, without ever using `assets.filerobot.com`.

import type { FilerobotAsset } from '../types/filerobot.types';
import type { Asset } from '../types/asset.types';
import { isVisibilityPublic } from './display-url';
import { formatToCdnUrl, signCdnUrl, type FilerobotUrlContext } from './filerobot-url';
import { getPdfPreviewUrl } from './media-url';
import { getFileTypeIconUrl } from './thumbnail';
import { setUrlParams } from './url-params';

/** The flat file description {@link getFilePresentation} works on. All URLs as the API gave them. */
export interface FilePresentationInput {
  /** File name with extension (used for the kind and the file-type icon). */
  name: string;
  /** MIME type (`image/png`) or the API's short type (`image`, `video`). */
  mime?: string;
  /** Size in bytes. */
  size?: number;
  /** Whether the file is public in the CDN; `undefined` = unknown. */
  isPublic?: boolean;
  /** `url.cdn` */
  cdnUrl?: string;
  /** `url.cdn_permalink` */
  cdnPermalinkUrl?: string;
  /** `url.public` (used for large-file downloads) */
  publicUrl?: string;
  /** API thumbnail (`info.thumbnail` ‖ `info.image_thumbnail` ‖ legacy `data.thumbnail`) */
  thumbnailUrl?: string;
  /** API preview (`info.preview`) */
  previewUrl?: string;
  /** API video poster (`info.video_thumbnail`) */
  videoThumbnailUrl?: string;
}

/** Options for {@link getFilePresentation}. */
export interface FilePresentationOptions {
  /**
   * SASS key of a **signed-in** user: the original of a non-public file (and the thumbnail / PDF
   * page built from it) gets `secret_key` on this container's hosts (needs `ctx.containerToken`). Never pass a security-template (guest) key — it doesn't unlock
   * private files. Without it, non-public files are returned unsigned (the CDN answers with an
   * error tile; fall back to `iconUrl`).
   */
  secretKey?: string | null;
  /**
   * Width for `thumbnailUrl` when it falls back to the CDN original (image or PDF page 1; default
   * 240). API-provided thumbnails are returned as given.
   */
  thumbnailWidth?: number;
  /** `func` for an image `thumbnailUrl` built from the CDN original (default `bound`). */
  thumbnailFunc?: string;
}

/** The URLs to render for a file. Empty string = nothing to render (use `iconUrl`). */
export interface FilePresentation {
  /**
   * Full-size display image (hero, preview panel, fullscreen). Size it with `setUrlParams`. It is
   * also the URL to put a preset or transform on (a camera RAW's is its API preview, since the CDN
   * can't transform those originals). For a URL that gets stored (preset, embed, download), take it
   * from a presentation built **without** `secretKey`, so it isn't signed.
   */
  imageUrl: string;
  /** Small preview for grids and lists (video poster, PDF page 1, sized image). */
  thumbnailUrl: string;
  /** The original bytes (video / audio playback, viewers). */
  originalUrl: string;
  /** Download link (`url.public` for files over 800 MB, the CDN URL otherwise). */
  downloadUrl: string;
  /** Hosted file-type icon: the fallback when the others are empty or fail to load. */
  iconUrl: string;
}

/** Files above this size download through `url.public` (Hub / Portals rule). */
const LARGE_FILE_BYTES = 800_000_000;

const RAW_EXTENSIONS = new Set(
  'dng cr2 cr3 crw nef nrw arw sr2 srf orf raw rw2 raf pef srw x3f erf mrw 3fr dcr kdc'.split(' '),
);
const RAW_MIMES = new Set(
  (
    'x-adobe-dng x-canon-cr2 x-canon-cr3 x-canon-crw x-nikon-nef x-nikon-nrw x-sony-arw x-sony-sr2 ' +
    'x-sony-srf x-olympus-orf x-panasonic-raw x-panasonic-rw2 x-fuji-raf x-pentax-pef x-samsung-srw ' +
    'x-sigma-x3f x-epson-erf x-minolta-mrw x-hasselblad-3fr x-kodak-dcr x-kodak-kdc'
  )
    .split(' ')
    .map((t) => `image/${t}`),
);
const IMAGE_EXTENSIONS = new Set(
  'jpg jpeg png gif webp svg avif bmp tif tiff heic heif ico psd'.split(' '),
);
const VIDEO_EXTENSIONS = new Set('mp4 webm mov m4v avi mkv ogv'.split(' '));

type FileKind = 'raw' | 'image' | 'video' | 'pdf' | 'other';

function fileKind(input: FilePresentationInput): FileKind {
  const mime = (input.mime ?? '').toLowerCase();
  const ext = (input.name.split('.').pop() ?? '').toLowerCase();
  // A full MIME type is authoritative; the API's short type (`image`, `application`) is only a
  // hint, so the extension decides first for it.
  const short = !mime.includes('/');
  if (RAW_MIMES.has(mime) || RAW_EXTENSIONS.has(ext)) return 'raw';
  if (mime.includes('pdf') || (short && ext === 'pdf')) return 'pdf';
  if (short && IMAGE_EXTENSIONS.has(ext)) return 'image';
  if (short && VIDEO_EXTENSIONS.has(ext)) return 'video';
  if (mime.startsWith('image')) return 'image';
  if (mime.startsWith('video')) return 'video';
  return 'other';
}

const first = (...urls: Array<string | undefined>): string => urls.find((u) => !!u) ?? '';

/**
 * Which URLs to render for a file, on the customer CDN (never `assets.filerobot.com`).
 *
 * | Kind | `thumbnailUrl` | `imageUrl` |
 * | --- | --- | --- |
 * | image | thumbnail → preview → CDN original (+ `w` / `func`) | CDN original → preview → thumbnail |
 * | camera RAW (DNG, CR2, …) | preview → thumbnail → transformed original (`w` / `func`, never the raw bytes) | same |
 * | PSD | as image: the CDN serves a PSD as JPEG even without params (checked 2026-11-10) | same |
 * | SVG | as image (transformed SVGs come back as `image/svg+xml`, or a raster with `force_format`) | same |
 * | video | poster → thumbnail → preview | same |
 * | PDF | thumbnail → preview → page 1 of the original (`w`) | same |
 * | other | thumbnail → preview → `''` | same |
 *
 * `originalUrl` = CDN original; `downloadUrl` = `publicUrl` for files over 800 MB or without a CDN
 * URL, else the CDN original; `iconUrl` = the hosted file-type icon (from the name's extension,
 * else the MIME type). Only the original (`cdnPermalinkUrl` ‖ `cdnUrl`)
 * goes through {@link formatToCdnUrl}, which also moves a CNAME onto the token host (CSP); it and
 * the URLs built from it are signed for non-public files when `options.secretKey` is given. API
 * thumbnails, previews, posters and `publicUrl` are returned as given.
 */
export function getFilePresentation(
  input: FilePresentationInput,
  ctx: FilerobotUrlContext,
  options: FilePresentationOptions = {},
): FilePresentation {
  const { thumbnailWidth = 240, thumbnailFunc = 'bound' } = options;
  const secretKey = input.isPublic ? null : options.secretKey;
  // Only the original is formatted and signed: the API returns thumbnails, previews, posters and
  // `url.public` ready to use (always `<token>.filerobot.com/.internal/…` or `store.`), and
  // `.internal` files are served without `secret_key` even for non-public files.
  const originalSource = first(input.cdnPermalinkUrl, input.cdnUrl);
  const original = originalSource
    ? signCdnUrl(formatToCdnUrl(originalSource, ctx), secretKey, ctx)
    : '';
  const thumbnail = input.thumbnailUrl ?? '';
  const preview = input.previewUrl ?? '';
  const poster = input.videoThumbnailUrl ?? '';

  let thumbnailUrl: string;
  let imageUrl: string;
  switch (fileKind(input)) {
    case 'raw': {
      // Camera RAW: browsers can't decode the original. Prefer the API preview / thumbnail; the
      // transformed original (`w` / `func`) is the last resort, for files without either (e.g.
      // folder covers). PSD is not here: it is an image (the CDN serves it as JPEG).
      const sized = original
        ? setUrlParams(original, { w: thumbnailWidth, func: thumbnailFunc })
        : '';
      thumbnailUrl = imageUrl = first(preview, thumbnail, sized);
      break;
    }
    case 'image': {
      const sized = original
        ? setUrlParams(original, { w: thumbnailWidth, func: thumbnailFunc })
        : '';
      thumbnailUrl = first(thumbnail, preview, sized);
      imageUrl = first(original, preview, thumbnail);
      break;
    }
    case 'video':
      thumbnailUrl = imageUrl = first(poster, thumbnail, preview);
      break;
    case 'pdf': {
      const page = original ? setUrlParams(getPdfPreviewUrl(original), { w: thumbnailWidth }) : '';
      thumbnailUrl = imageUrl = first(thumbnail, preview, page);
      break;
    }
    default:
      thumbnailUrl = imageUrl = first(thumbnail, preview);
  }

  const large = (input.size ?? 0) > LARGE_FILE_BYTES;
  return {
    imageUrl,
    thumbnailUrl,
    originalUrl: original,
    // `url.public` for large files (Hub rule), and when there is no CDN URL at all.
    downloadUrl: (large || !original) && input.publicUrl ? input.publicUrl : original,
    iconUrl: getFileTypeIconUrl(input.name, input.mime),
  };
}

/** A raw Files API object carries a `url` object; the normalised `Asset` flattens it to `cdnUrl`. */
function isRawFile(file: FilerobotAsset | Asset): file is FilerobotAsset {
  const url = (file as FilerobotAsset).url;
  return typeof url === 'object' && url !== null;
}

/**
 * Map a file onto {@link FilePresentationInput}: the raw Files API object (`url.cdn`, `info.*`,
 * `visibility`) or dam-core's normalised {@link Asset} (`cdnUrl`, `thumbnailUrl`, `isPublic`).
 */
export function mapToFilePresentationInput(file: FilerobotAsset | Asset): FilePresentationInput {
  if (!isRawFile(file)) {
    return {
      name: file.name,
      mime: file.fileType || file.type,
      size: file.size,
      isPublic: file.isPublic,
      cdnUrl: file.cdnUrl,
      thumbnailUrl: file.thumbnailUrl,
    };
  }
  const info = file.info ?? {};
  return {
    name: file.name,
    mime: file.mime || file.type,
    size: file.size?.bytes,
    isPublic: file.visibility === undefined ? undefined : isVisibilityPublic(file.visibility),
    cdnUrl: file.url?.cdn,
    cdnPermalinkUrl: file.url?.cdn_permalink,
    publicUrl: file.url?.public,
    // Portals' order: `thumbnail`, then `image_thumbnail`, then the legacy `data.thumbnail`.
    thumbnailUrl:
      (info.thumbnail as string | undefined) ||
      (info.image_thumbnail as string | undefined) ||
      file.data?.thumbnail,
    previewUrl: info.preview as string | undefined,
    videoThumbnailUrl: info.video_thumbnail as string | undefined,
  };
}
