import { DamApiError } from '../api/dam-client';

/** The key a folder scope lives under in a filters record (`{ folders: { values: [...] } }`). */
export const FOLDERS_FILTER_KEY = 'folders';

/**
 * What a folder scope reads from a `folders` filter: the folder paths and the operator applied to
 * them. Any richer filter shape (asset-picker's `StringFilter`, Hub's) satisfies it.
 */
export interface FolderScopeFilter {
  values?: string[];
  operator?: string;
}

/**
 * The API's answer for a folder path that doesn't exist (404 `DIR_NOT_FOUND`, PROD v2610.08.01) —
 * e.g. a folder deleted or renamed after it was put in `defaultFilters`. Such a folder holds no
 * assets; it must not take the other selected folders down with it.
 */
export function isFolderNotFound(error: unknown): boolean {
  return error instanceof DamApiError && error.code === 'DIR_NOT_FOUND';
}

/**
 * Folder paths are compared in one shape: leading slash, no trailing slash. Case is kept — the
 * DAM treats paths as case-sensitive, so folding it would merge two real folders.
 */
export function normalizeFolderPath(path: string): string {
  const trimmed = (path ?? '').trim();
  if (!trimmed || trimmed === '/') return '/';
  const withLeading = trimmed.startsWith('/') ? trimmed : `/${trimmed}`;
  return withLeading.replace(/\/+$/, '') || '/';
}

function isAncestorPath(ancestor: string, path: string): boolean {
  return ancestor === '/' ? path !== '/' : path.startsWith(`${ancestor}/`);
}

/**
 * Drop every folder already contained by another one in the list. Assets-view fetches are
 * recursive, so an ancestor's results include its descendants' — keeping both would fetch (and
 * count) the same assets twice.
 */
export function dedupeOverlappingFolderPaths(paths: string[]): string[] {
  const normalized = [...new Set(paths.map(normalizeFolderPath))];
  return normalized.filter(
    (path) => !normalized.some((other) => other !== path && isAncestorPath(other, path)),
  );
}

/** Operators a folder scope can honour — it is an inclusion list ("in these folders"). */
const INCLUDE_OPERATORS = new Set([undefined, '', ':', '=']);

/** Whether `path` is one of `folders` or inside one of them. */
export function isPathInFolders(path: string, folders: string[]): boolean {
  const key = normalizeFolderPath(path);
  return folders.some((folder) => folder === key || isAncestorPath(folder, key));
}

/**
 * Narrow each path to `bounds`: a path inside a bound (or equal to it) is kept, an ancestor of
 * some bounds becomes those bounds, anything else is dropped. Never widens past the bounds.
 */
function clampToFolders(paths: string[], bounds: string[]): string[] {
  return paths.flatMap((path) =>
    bounds.some((bound) => bound === path || isAncestorPath(bound, path))
      ? [path]
      : bounds.filter((bound) => isAncestorPath(path, bound)),
  );
}

/**
 * The folders the `folderFilterOptions` config offers, clamped to `rootPath` and deduped — the
 * list the Folders filter shows, and the Assets view's scope while no folder is picked. `null`
 * when the option isn't set (or is `[]`): the filter browses the whole tree as usual.
 */
export function getFolderFilterOptions(
  options: string[] | undefined,
  rootPath = '/',
): string[] | null {
  const values = (options ?? []).filter((v) => typeof v === 'string' && v.trim());
  if (values.length === 0) return null;
  return dedupeOverlappingFolderPaths(
    clampToFolders(values.map(normalizeFolderPath), [normalizeFolderPath(rootPath)]),
  );
}

/**
 * The folders the Assets view is narrowed to by the `folders` filter:
 * - `[]` — no folders filter, browse as usual;
 * - a list — fetch from exactly these folders (overlaps removed);
 * - `null` — the filter can't be honoured, so nothing may be shown (fail closed): an exclusion
 *   operator (`:-`, `!=`…), which a fetch scope can't express, or folders that all lie outside
 *   `rootPath` (or outside `options`).
 *
 * The filter is a fetch scope, not a search clause — the backend rejects `folders:` in `q`
 * (`w2501_invalid_meta_key_filter`) — so it is resolved here and never serialized. Each folder is
 * clamped to `rootPath`: an ancestor of the root (e.g. `/`) narrows to the root itself, a folder
 * outside it is dropped, so a configured value can never widen the view past the root.
 *
 * `options` (from `getFolderFilterOptions`) bounds the scope the same way, and is the scope
 * itself when no folder is picked — with options set the Assets view never falls back to the
 * whole root (FRA-11365: "archive opt-in", never the rest of the DAM).
 */
export function getFolderScope(
  filter: FolderScopeFilter | undefined,
  rootPath = '/',
  options: string[] | null = null,
): string[] | null {
  const values = filter?.values?.filter((v) => typeof v === 'string' && v.trim()) ?? [];
  if (values.length === 0) return options ? (options.length > 0 ? options : null) : [];
  if (!INCLUDE_OPERATORS.has(filter?.operator)) return null;

  let clamped = clampToFolders(values.map(normalizeFolderPath), [normalizeFolderPath(rootPath)]);
  if (options) clamped = clampToFolders(clamped, options);
  if (clamped.length === 0) return null;
  return dedupeOverlappingFolderPaths(clamped);
}

/**
 * A `folders` filter value rewritten as what `options` narrow it to (`/` → every option under it),
 * so the Folders filter — which lists only the options — shows exactly what applies and the user
 * can untick it. Returned as is when it has no values or narrows to nothing: that one shows no
 * assets (fail closed), and its chip is what explains the empty view.
 */
export function narrowFolderFilter<T extends FolderScopeFilter>(
  filter: T | undefined,
  rootPath: string,
  options: string[],
): T | undefined {
  if (!filter?.values?.some((v) => typeof v === 'string' && v.trim())) return filter;
  const scope = getFolderScope(filter, rootPath, options);
  return scope ? { ...filter, values: scope } : filter;
}

/** The `folders` filter in effect: an applied one wins over a forced one, like every other key. */
export function pickFolderFilter<T extends FolderScopeFilter>(
  forced: Partial<Record<string, T | undefined>>,
  applied: Partial<Record<string, T | undefined>>,
): T | undefined {
  return applied[FOLDERS_FILTER_KEY] ?? forced[FOLDERS_FILTER_KEY];
}

/** Last path segment, for chip summaries (`/marketing/archive` → `archive`). */
export function folderDisplayName(path: string): string {
  const normalized = normalizeFolderPath(path);
  return normalized === '/' ? '/' : normalized.slice(normalized.lastIndexOf('/') + 1);
}
